// A 2-slot queue of 4-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module tx_buffer #(
    parameter WIDTH = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             enq_valid,
    output wire             enq_ready,
    input  wire [WIDTH-1:0] enq_data,
    output wire             deq_valid,
    input  wire             deq_ready,
    output wire [WIDTH-1:0] deq_data,
    output wire [1:0]       level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [1:0] valid_q;
    reg [0:0] wptr_q;
    reg [0:0] rptr_q;
    reg [1:0] cnt_q;
    reg full_r, empty_r;

    initial valid_q = 2'd0;
    initial wptr_q = 1'd0;
    initial rptr_q = 1'd0;
    initial cnt_q = 2'd0;
    initial full_r = 1'b0;
    initial empty_r = 1'b1;

    assign enq_ready  = !full_r;
    assign deq_valid = !empty_r;
    wire do_push = enq_valid && enq_ready;
    wire do_pop  = deq_valid && deq_ready;
    assign deq_data = ram[rptr_q];
    assign level = cnt_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q] <= enq_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid_q <= 2'd0;
            wptr_q <= 1'd0;
            rptr_q <= 1'd0;
            cnt_q <= 2'd0;
            full_r <= 1'b0;
            empty_r <= 1'b1;
        end else begin
            if (do_push) begin
                valid_q[wptr_q] <= 1'b1;
                wptr_q <= wptr_q + 1'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q] <= 1'b0;
                rptr_q <= rptr_q + 1'd1;
            end
            if (do_push && !do_pop) begin
                cnt_q <= cnt_q + 2'd1;
                full_r <= (cnt_q == 2'd1);
                empty_r <= 1'b0;
            end else if (do_pop && !do_push) begin
                cnt_q <= cnt_q - 2'd1;
                full_r <= 1'b0;
                empty_r <= (cnt_q == 2'd1);
            end
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert (cnt_q == valid_q[0] + valid_q[1]);
endmodule

// A 2-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full.
module desc_fifo #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [1:0]       fill_level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [1:0] occupied;
    reg [0:0] tail;
    reg [0:0] head;
    reg [1:0] fill;

    initial occupied = 2'd0;
    initial tail = 1'd0;
    initial head = 1'd0;
    initial fill = 2'd0;

    assign full  = (fill == 2'd2);
    assign empty = (fill == 2'd0);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= push_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            occupied <= 2'd0;
            tail <= 1'd0;
            head <= 1'd0;
            fill <= 2'd0;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 1'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 1'd1;
            end
            if (do_push && !do_pop)
                fill <= fill + 2'd1;
            else if (do_pop && !do_push)
                fill <= fill - 2'd1;
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !occupied[tail]);
endmodule

// A 32-slot queue of 8-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module tag_buffer #(
    parameter WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [5:0]       occupancy
);
    localparam DEPTH = 32;

    reg [WIDTH-1:0] entries [0:DEPTH-1];
    reg [31:0] entry_valid;
    reg [5:0] waddr;
    reg [5:0] raddr;

    initial entry_valid = 32'd0;
    initial waddr = 6'd0;
    initial raddr = 6'd0;

    assign full  = (waddr == {~raddr[5], raddr[4:0]});
    assign empty = (waddr == raddr);
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = entries[raddr[4:0]];
    assign occupancy = waddr - raddr;

    always @(posedge clk) begin
        if (do_push) entries[waddr[4:0]] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 32'd0;
            waddr <= 6'd0;
            raddr <= 6'd0;
        end else begin
            if (do_push) begin
                entry_valid[waddr[4:0]] <= 1'b1;
                waddr <= waddr + 6'd1;
            end
            if (do_pop) begin
                entry_valid[raddr[4:0]] <= 1'b0;
                raddr <= raddr + 6'd1;
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (empty || entry_valid[raddr[4:0]]);
endmodule

// A 2-entry lookup table of 12-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module tag_cache #(
    parameter KEY_W = 12,
    parameter VAL_W = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_valid,
    output wire             wr_ready,
    input  wire [KEY_W-1:0] wr_key,
    input  wire [VAL_W-1:0] wr_val,
    input  wire             del_valid,
    input  wire [KEY_W-1:0] del_key,
    input  wire [KEY_W-1:0] rd_key,
    output wire             rd_hit,
    output wire [VAL_W-1:0] rd_val
);
    localparam N = 2;

    reg [N-1:0] valid;
    reg [KEY_W-1:0] keys [0:N-1];
    reg [VAL_W-1:0] vals [0:N-1];

    initial valid = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lk_match;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lk_match[i0] = valid[i0] && (keys[i0] == rd_key);
            if (lk_match[i0]) lk_val_r = vals[i0];
        end
    end
    assign rd_hit = |lk_match;
    assign rd_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg wr_hit, any_free;
    reg [0:0] wr_slot, free_slot;
    integer i1;
    always @(*) begin
        wr_hit = 1'b0;
        wr_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (valid[i1] && (keys[i1] == wr_key)) begin
                wr_hit = 1'b1;
                wr_slot = i1;
            end
            if (!valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg del_hit;
    reg [0:0] del_slot;
    integer i2;
    always @(*) begin
        del_hit = 1'b0;
        del_slot = 1'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (valid[i2] && (keys[i2] == del_key)) begin
                del_hit = 1'b1;
                del_slot = i2;
            end
    end

    assign wr_ready = (wr_hit || any_free) && !del_valid;
    wire [0:0] target = wr_hit ? wr_slot : free_slot;
    wire do_ins = wr_valid && wr_ready;
    wire do_inv = del_valid && del_hit;

    always @(posedge clk) begin
        if (rst) begin
            valid <= 2'd0;
        end else if (do_inv) begin
            valid[del_slot] <= 1'b0;
        end else if (do_ins) begin
            valid[target] <= 1'b1;
            keys[target] <= wr_key;
            vals[target] <= wr_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lk_match[0] + lk_match[1] <= 2'd1);
endmodule

// A 8-entry lookup table of 4-bit keys and 8-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module tag_table #(
    parameter KEY_W = 4,
    parameter VAL_W = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
    input  wire [VAL_W-1:0] ins_val,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 8;

    reg [N-1:0] valid;
    reg [KEY_W-1:0] keys [0:N-1];
    reg [VAL_W-1:0] vals [0:N-1];
    reg [2:0] victim;

    initial valid = 8'd0;
    initial victim = 3'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lk_match;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lk_match[i0] = valid[i0] && (keys[i0] == lk_key);
            if (lk_match[i0]) lk_val_r = vals[i0];
        end
    end
    assign lk_hit = |lk_match;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [2:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 3'd0;
        any_free = 1'b0;
        free_slot = 3'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (valid[i1] && (keys[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign ins_ready = 1'b1;
    wire [2:0] target = ins_hit ? ins_slot : (any_free ? free_slot : victim);
    wire do_ins = ins_valid && ins_ready;

    always @(posedge clk) begin
        if (rst) begin
            valid <= 8'd0;
            victim <= 3'd0;
        end else if (do_ins) begin
            valid[target] <= 1'b1;
            keys[target] <= ins_key;
            vals[target] <= ins_val;
            if (!ins_hit && !any_free) victim <= victim + 3'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lk_match[0] + lk_match[1] + lk_match[2] + lk_match[3] + lk_match[4] + lk_match[5] + lk_match[6] + lk_match[7] <= 4'd1);
endmodule

// A 16-slot queue of 4-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module tag_buffer #(
    parameter WIDTH = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [4:0]       level
);
    localparam DEPTH = 16;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [15:0] slot_full;
    reg [3:0] wr_ptr;
    reg [3:0] rd_ptr;
    reg [4:0] count;
    reg full_q, empty_q;

    initial slot_full = 16'd0;
    initial wr_ptr = 4'd0;
    initial rd_ptr = 4'd0;
    initial count = 5'd0;
    initial full_q = 1'b0;
    initial empty_q = 1'b1;

    assign full  = full_q;
    assign empty = empty_q;
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = mem[rd_ptr];
    assign level = count;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            slot_full <= 16'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
            count <= 5'd0;
            full_q <= 1'b0;
            empty_q <= 1'b1;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr] <= 1'b1;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr] <= 1'b0;
                rd_ptr <= rd_ptr + 4'd1;
            end
            if (do_push && !do_pop) begin
                count <= count + 5'd1;
                full_q <= (count == 5'd15);
                empty_q <= 1'b0;
            end else if (do_pop && !do_push) begin
                count <= count - 5'd1;
                full_q <= 1'b0;
                empty_q <= (count == 5'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (empty || slot_full[rd_ptr]);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module txn_free_list (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    output wire             take_valid,
    input  wire             take_ready,
    output wire [1:0]       take_id,
    input  wire             give_valid,
    input  wire [1:0]       give_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] in_use;
    reg [1:0] free_ids [0:N-1];
    reg [1:0] rd_ptr;
    reg [1:0] wr_ptr;
    reg [2:0] num_free;

    initial in_use = 4'd0;
    initial rd_ptr = 2'd0;
    initial wr_ptr = 2'd0;
    initial num_free = 3'd4;
    initial free_ids[0] = 2'd0;
    initial free_ids[1] = 2'd1;
    initial free_ids[2] = 2'd2;
    initial free_ids[3] = 2'd3;

    assign take_valid = (num_free != 3'd0);
    assign take_id = free_ids[rd_ptr];
    assign free_count = num_free;
    wire do_alloc = take_valid && take_ready;
    wire do_rel = give_valid && in_use[give_id];

    always @(posedge clk) begin
        if (rst || flush) begin
            in_use <= 4'd0;
            rd_ptr <= 2'd0;
            wr_ptr <= 2'd0;
            num_free <= 3'd4;
            free_ids[0] <= 2'd0;
            free_ids[1] <= 2'd1;
            free_ids[2] <= 2'd2;
            free_ids[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                in_use[free_ids[rd_ptr]] <= 1'b1;
                rd_ptr <= rd_ptr + 2'd1;
            end
            if (do_rel) begin
                in_use[give_id] <= 1'b0;
                free_ids[wr_ptr] <= give_id;
                wr_ptr <= wr_ptr + 2'd1;
            end
            if (do_alloc && !do_rel)
                num_free <= num_free - 3'd1;
            else if (do_rel && !do_alloc)
                num_free <= num_free + 3'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (num_free + in_use[0] + in_use[1] + in_use[2] + in_use[3] == 3'd4);
endmodule

// A 4-entry lookup table of 12-bit keys and 8-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module session_map #(
    parameter KEY_W = 12,
    parameter VAL_W = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
    input  wire [VAL_W-1:0] ins_val,
    input  wire             inv_valid,
    input  wire [KEY_W-1:0] inv_key,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 4;

    reg [N-1:0] v_q;
    reg [KEY_W-1:0] key_q [0:N-1];
    reg [VAL_W-1:0] val_q [0:N-1];
    reg [1:0] victim;

    initial v_q = 4'd0;
    initial victim = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] match_q;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            match_q[i0] = v_q[i0] && (key_q[i0] == lk_key);
            if (match_q[i0]) lk_val_r = val_q[i0];
        end
    end
    assign lk_hit = |match_q;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [1:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (v_q[i1] && (key_q[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg inv_hit;
    reg [1:0] inv_slot;
    integer i2;
    always @(*) begin
        inv_hit = 1'b0;
        inv_slot = 2'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (v_q[i2] && (key_q[i2] == inv_key)) begin
                inv_hit = 1'b1;
                inv_slot = i2;
            end
    end

    assign ins_ready = !inv_valid;
    wire [1:0] target = ins_hit ? ins_slot : (any_free ? free_slot : victim);
    wire do_ins = ins_valid && ins_ready;
    wire do_inv = inv_valid && inv_hit;

    always @(posedge clk) begin
        if (rst) begin
            v_q <= 4'd0;
            victim <= 2'd0;
        end else if (do_inv) begin
            v_q[inv_slot] <= 1'b0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= ins_key;
            val_q[target] <= ins_val;
            if (!ins_hit && !any_free) victim <= victim + 2'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (match_q[0] + match_q[1] + match_q[2] + match_q[3] <= 3'd1);
endmodule

// A 2-entry lookup table of 4-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module route_map #(
    parameter KEY_W = 4,
    parameter VAL_W = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
