    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 2;

    reg [N-1:0] valid;
    reg [KEY_W-1:0] keys [0:N-1];
    reg [VAL_W-1:0] vals [0:N-1];
    reg [0:0] victim;

    initial valid = 2'd0;
    initial victim = 1'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lk_match;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lk_match[i0] = valid[i0] && (keys[i0] == lk_key);
            if (lk_match[i0]) lk_val_r = vals[i0];
        end
    end
    assign lk_hit = |lk_match;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [0:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (valid[i1] && (keys[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign ins_ready = 1'b1;
    wire [0:0] target = ins_hit ? ins_slot : (any_free ? free_slot : victim);
    wire do_ins = ins_valid && ins_ready;

    always @(posedge clk) begin
        if (rst) begin
            valid <= 2'd0;
            victim <= 1'd0;
        end else if (do_ins) begin
            valid[target] <= 1'b1;
            keys[target] <= ins_key;
            vals[target] <= ins_val;
            if (!ins_hit && !any_free) victim <= victim + 1'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lk_match[0] + lk_match[1] <= 2'd1);
endmodule

// A pool of 8 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module tag_free_list (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    output wire             get_valid,
    input  wire             get_ready,
    output wire [2:0]       get_id,
    input  wire             put_valid,
    input  wire [2:0]       put_id,
    output wire [3:0]       free_count
);
    localparam N = 8;

    reg [N-1:0] busy;
    reg [2:0] free_list [0:N-1];
    reg [2:0] fl_head;
    reg [2:0] fl_tail;
    reg [3:0] fl_count;

    initial busy = 8'd0;
    initial fl_head = 3'd0;
    initial fl_tail = 3'd0;
    initial fl_count = 4'd8;
    initial free_list[0] = 3'd0;
    initial free_list[1] = 3'd1;
    initial free_list[2] = 3'd2;
    initial free_list[3] = 3'd3;
    initial free_list[4] = 3'd4;
    initial free_list[5] = 3'd5;
    initial free_list[6] = 3'd6;
    initial free_list[7] = 3'd7;

    assign get_valid = (fl_count != 4'd0);
    assign get_id = free_list[fl_head];
    assign free_count = fl_count;
    wire do_alloc = get_valid && get_ready;
    wire do_rel = put_valid && busy[put_id];

    always @(posedge clk) begin
        if (rst || flush) begin
            busy <= 8'd0;
            fl_head <= 3'd0;
            fl_tail <= 3'd0;
            fl_count <= 4'd8;
            free_list[0] <= 3'd0;
            free_list[1] <= 3'd1;
            free_list[2] <= 3'd2;
            free_list[3] <= 3'd3;
            free_list[4] <= 3'd4;
            free_list[5] <= 3'd5;
            free_list[6] <= 3'd6;
            free_list[7] <= 3'd7;
        end else begin
            if (do_alloc) begin
                busy[free_list[fl_head]] <= 1'b1;
                fl_head <= fl_head + 3'd1;
            end
            if (do_rel) begin
                busy[put_id] <= 1'b0;
                free_list[fl_tail] <= put_id;
                fl_tail <= fl_tail + 3'd1;
            end
            if (do_alloc && !do_rel)
                fl_count <= fl_count - 4'd1;
            else if (do_rel && !do_alloc)
                fl_count <= fl_count + 4'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (fl_count + busy[0] + busy[1] + busy[2] + busy[3] + busy[4] + busy[5] + busy[6] + busy[7] == 4'd8);
endmodule

// A 2-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full.
module cmd_queue #(
    parameter WIDTH = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [1:0]       fill_level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [1:0] occupied;
    reg [0:0] tail;
    reg [0:0] head;
    reg [1:0] fill;

    initial occupied = 2'd0;
    initial tail = 1'd0;
    initial head = 1'd0;
    initial fill = 2'd0;

    assign full  = (fill == 2'd2);
    assign empty = (fill == 2'd0);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= push_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            occupied <= 2'd0;
            tail <= 1'd0;
            head <= 1'd0;
            fill <= 2'd0;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 1'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 1'd1;
            end
            if (do_push && !do_pop)
                fill <= fill + 2'd1;
            else if (do_pop && !do_push)
                fill <= fill - 2'd1;
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !occupied[tail]);
endmodule

// A 2-entry lookup table of 32-bit keys and 8-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module id_table #(
    parameter KEY_W = 32,
    parameter VAL_W = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_valid,
    output wire             wr_ready,
    input  wire [KEY_W-1:0] wr_key,
    input  wire [VAL_W-1:0] wr_val,
    input  wire [KEY_W-1:0] rd_key,
    output wire             rd_hit,
    output wire [VAL_W-1:0] rd_val
);
    localparam N = 2;

    reg [N-1:0] in_use;
    reg [KEY_W-1:0] addr_tag [0:N-1];
    reg [VAL_W-1:0] payload [0:N-1];
    reg [0:0] victim;

    initial in_use = 2'd0;
    initial victim = 1'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lookup_hit;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lookup_hit[i0] = in_use[i0] && (addr_tag[i0] == rd_key);
            if (lookup_hit[i0]) lk_val_r = payload[i0];
        end
    end
    assign rd_hit = |lookup_hit;
    assign rd_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg wr_hit, any_free;
    reg [0:0] wr_slot, free_slot;
    integer i1;
    always @(*) begin
        wr_hit = 1'b0;
        wr_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (in_use[i1] && (addr_tag[i1] == wr_key)) begin
                wr_hit = 1'b1;
                wr_slot = i1;
            end
            if (!in_use[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign wr_ready = 1'b1;
    wire [0:0] target = wr_hit ? wr_slot : (any_free ? free_slot : victim);
    wire do_ins = wr_valid && wr_ready;

    always @(posedge clk) begin
        if (rst) begin
            in_use <= 2'd0;
            victim <= 1'd0;
        end else if (do_ins) begin
            in_use[target] <= 1'b1;
            addr_tag[target] <= wr_key;
            payload[target] <= wr_val;
            if (!wr_hit && !any_free) victim <= victim + 1'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lookup_hit[0] + lookup_hit[1] <= 2'd1);
endmodule

// A 4-entry lookup table of 32-bit keys and 4-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module session_map #(
    parameter KEY_W = 32,
    parameter VAL_W = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_valid,
    output wire             wr_ready,
    input  wire [KEY_W-1:0] wr_key,
    input  wire [VAL_W-1:0] wr_val,
    input  wire             del_valid,
    input  wire [KEY_W-1:0] del_key,
    input  wire [KEY_W-1:0] rd_key,
    output wire             rd_hit,
    output wire [VAL_W-1:0] rd_val
);
    localparam N = 4;

    reg [N-1:0] valid;
    reg [KEY_W-1:0] keys [0:N-1];
    reg [VAL_W-1:0] vals [0:N-1];
    reg [1:0] victim;

    initial valid = 4'd0;
    initial victim = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lk_match;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lk_match[i0] = valid[i0] && (keys[i0] == rd_key);
            if (lk_match[i0]) lk_val_r = vals[i0];
        end
    end
    assign rd_hit = |lk_match;
    assign rd_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg wr_hit, any_free;
    reg [1:0] wr_slot, free_slot;
    integer i1;
    always @(*) begin
        wr_hit = 1'b0;
        wr_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (valid[i1] && (keys[i1] == wr_key)) begin
                wr_hit = 1'b1;
                wr_slot = i1;
            end
            if (!valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg del_hit;
    reg [1:0] del_slot;
    integer i2;
    always @(*) begin
        del_hit = 1'b0;
        del_slot = 2'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (valid[i2] && (keys[i2] == del_key)) begin
                del_hit = 1'b1;
                del_slot = i2;
            end
    end

    assign wr_ready = !del_valid;
    wire [1:0] target = wr_hit ? wr_slot : (any_free ? free_slot : victim);
    wire do_ins = wr_valid && wr_ready;
    wire do_inv = del_valid && del_hit;

    always @(posedge clk) begin
        if (rst) begin
            valid <= 4'd0;
            victim <= 2'd0;
        end else if (do_inv) begin
            valid[del_slot] <= 1'b0;
        end else if (do_ins) begin
            valid[target] <= 1'b1;
            keys[target] <= wr_key;
            vals[target] <= wr_val;
            if (!wr_hit && !any_free) victim <= victim + 2'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lk_match[0] + lk_match[1] + lk_match[2] + lk_match[3] <= 3'd1);
endmodule

// A 64-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full.
module job_queue #(
    parameter WIDTH = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             s_axis_tvalid,
    output wire             s_axis_tready,
    input  wire [WIDTH-1:0] s_axis_tdata,
    output wire             m_axis_tvalid,
    input  wire             m_axis_tready,
    output wire [WIDTH-1:0] m_axis_tdata,
    output wire [6:0]       fill_level
);
    localparam DEPTH = 64;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [63:0] occupied;
    reg [5:0] tail;
    reg [5:0] head;
    reg [6:0] fill;

    initial occupied = 64'd0;
    initial tail = 6'd0;
    initial head = 6'd0;
    initial fill = 7'd0;

    assign s_axis_tready  = (fill != 7'd64);
    assign m_axis_tvalid = (fill != 7'd0);
    wire do_push = s_axis_tvalid && s_axis_tready;
    wire do_pop  = m_axis_tvalid && m_axis_tready;
    assign m_axis_tdata = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= s_axis_tdata;
    end

    always @(posedge clk) begin
        if (rst) begin
            occupied <= 64'd0;
            tail <= 6'd0;
            head <= 6'd0;
            fill <= 7'd0;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 6'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 6'd1;
            end
            if (do_push && !do_pop)
                fill <= fill + 7'd1;
            else if (do_pop && !do_push)
                fill <= fill - 7'd1;
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (!s_axis_tready || !occupied[tail]);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module slot_pool (
    input  wire             clk,
    input  wire             rst,
    output wire             get_valid,
    input  wire             get_ready,
    output wire [1:0]       get_id,
    input  wire             put_valid,
    input  wire [1:0]       put_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] busy;
    reg [1:0] free_list [0:N-1];
    reg [1:0] fl_head;
    reg [1:0] fl_tail;
    reg [2:0] fl_count;

    initial busy = 4'd0;
    initial fl_head = 2'd0;
    initial fl_tail = 2'd0;
    initial fl_count = 3'd4;
    initial free_list[0] = 2'd0;
    initial free_list[1] = 2'd1;
    initial free_list[2] = 2'd2;
    initial free_list[3] = 2'd3;

    assign get_valid = (fl_count != 3'd0);
    assign get_id = free_list[fl_head];
    assign free_count = fl_count;
    wire do_alloc = get_valid && get_ready;
    wire do_rel = put_valid && busy[put_id];

    always @(posedge clk) begin
        if (rst) begin
            busy <= 4'd0;
            fl_head <= 2'd0;
            fl_tail <= 2'd0;
            fl_count <= 3'd4;
            free_list[0] <= 2'd0;
            free_list[1] <= 2'd1;
            free_list[2] <= 2'd2;
            free_list[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                busy[free_list[fl_head]] <= 1'b1;
                fl_head <= fl_head + 2'd1;
            end
            if (do_rel) begin
                busy[put_id] <= 1'b0;
                free_list[fl_tail] <= put_id;
                fl_tail <= fl_tail + 2'd1;
            end
            if (do_alloc && !do_rel)
                fl_count <= fl_count - 3'd1;
            else if (do_rel && !do_alloc)
                fl_count <= fl_count + 3'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (fl_count + busy[0] + busy[1] + busy[2] + busy[3] == 3'd4);
endmodule

// A 4-slot queue of 32-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module rx_buffer #(
    parameter WIDTH = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [2:0]       occupancy
);
    localparam DEPTH = 4;

    reg [WIDTH-1:0] entries [0:DEPTH-1];
    reg [3:0] entry_valid;
    reg [2:0] waddr;
    reg [2:0] raddr;

    initial entry_valid = 4'd0;
    initial waddr = 3'd0;
    initial raddr = 3'd0;

    assign full  = (waddr == {~raddr[2], raddr[1:0]});
    assign empty = (waddr == raddr);
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = entries[raddr[1:0]];
    assign occupancy = waddr - raddr;

    always @(posedge clk) begin
        if (do_push) entries[waddr[1:0]] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 4'd0;
            waddr <= 3'd0;
            raddr <= 3'd0;
        end else begin
            if (do_push) begin
                entry_valid[waddr[1:0]] <= 1'b1;
                waddr <= waddr + 3'd1;
            end
            if (do_pop) begin
                entry_valid[raddr[1:0]] <= 1'b0;
                raddr <= raddr + 3'd1;
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !entry_valid[waddr[1:0]]);
endmodule

// A 8-entry lookup table of 4-bit keys and 4-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module tlb_table #(
    parameter KEY_W = 4,
    parameter VAL_W = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
    input  wire [VAL_W-1:0] ins_val,
    input  wire             inv_valid,
    input  wire [KEY_W-1:0] inv_key,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 8;

    reg [N-1:0] valid;
    reg [KEY_W-1:0] keys [0:N-1];
    reg [VAL_W-1:0] vals [0:N-1];
    reg [2:0] victim;

    initial valid = 8'd0;
    initial victim = 3'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lk_match;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lk_match[i0] = valid[i0] && (keys[i0] == lk_key);
            if (lk_match[i0]) lk_val_r = vals[i0];
        end
    end
    assign lk_hit = |lk_match;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [2:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 3'd0;
        any_free = 1'b0;
        free_slot = 3'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (valid[i1] && (keys[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg inv_hit;
    reg [2:0] inv_slot;
    integer i2;
    always @(*) begin
        inv_hit = 1'b0;
        inv_slot = 3'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (valid[i2] && (keys[i2] == inv_key)) begin
                inv_hit = 1'b1;
                inv_slot = i2;
            end
    end

    assign ins_ready = !inv_valid;
    wire [2:0] target = ins_hit ? ins_slot : (any_free ? free_slot : victim);
    wire do_ins = ins_valid && ins_ready;
    wire do_inv = inv_valid && inv_hit;

    always @(posedge clk) begin
        if (rst) begin
            valid <= 8'd0;
            victim <= 3'd0;
        end else if (do_inv) begin
            valid[inv_slot] <= 1'b0;
        end else if (do_ins) begin
            valid[target] <= 1'b1;
            keys[target] <= ins_key;
            vals[target] <= ins_val;
            if (!ins_hit && !any_free) victim <= victim + 3'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lk_match[0] + lk_match[1] + lk_match[2] + lk_match[3] + lk_match[4] + lk_match[5] + lk_match[6] + lk_match[7] <= 4'd1);
endmodule

// A 16-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full.
module rx_queue #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [4:0]       level
);
    localparam DEPTH = 16;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [15:0] slot_full;
    reg [3:0] wr_ptr;
    reg [3:0] rd_ptr;
    reg [4:0] count;

    initial slot_full = 16'd0;
    initial wr_ptr = 4'd0;
    initial rd_ptr = 4'd0;
    initial count = 5'd0;

    assign full  = (count == 5'd16);
    assign empty = (count == 5'd0);
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = mem[rd_ptr];
    assign level = count;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            slot_full <= 16'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
            count <= 5'd0;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr] <= 1'b1;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr] <= 1'b0;
                rd_ptr <= rd_ptr + 4'd1;
            end
            if (do_push && !do_pop)
                count <= count + 5'd1;
            else if (do_pop && !do_push)
                count <= count - 5'd1;
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert (count == slot_full[0] + slot_full[1] + slot_full[2] + slot_full[3] + slot_full[4] + slot_full[5] + slot_full[6] + slot_full[7] + slot_full[8] + slot_full[9] + slot_full[10] + slot_full[11] + slot_full[12] + slot_full[13] + slot_full[14] + slot_full[15]);
endmodule

// A 2-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module desc_queue #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [1:0]       fill_level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [1:0] occupied;
    reg [0:0] tail;
    reg [0:0] head;
    reg [1:0] fill;
    reg is_full, is_empty;

    initial occupied = 2'd0;
    initial tail = 1'd0;
    initial head = 1'd0;
    initial fill = 2'd0;
    initial is_full = 1'b0;
    initial is_empty = 1'b1;

    assign full  = is_full;
    assign empty = is_empty;
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= push_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            occupied <= 2'd0;
            tail <= 1'd0;
            head <= 1'd0;
            fill <= 2'd0;
            is_full <= 1'b0;
            is_empty <= 1'b1;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 1'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 1'd1;
            end
            if (do_push && !do_pop) begin
                fill <= fill + 2'd1;
                is_full <= (fill == 2'd1);
                is_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                fill <= fill - 2'd1;
                is_full <= 1'b0;
                is_empty <= (fill == 2'd1);
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !occupied[tail]);
