    always @(posedge clk) begin
        if (rst) begin
            slot_full <= 2'd0;
            wr_ptr <= 1'd0;
            rd_ptr <= 1'd0;
            count <= 2'd0;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr] <= 1'b1;
                wr_ptr <= wr_ptr + 1'd1;
