        wr_hit = 1'b0;
        wr_slot = 3'd0;
        any_free = 1'b0;
        free_slot = 3'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (in_use[i1] && (addr_tag[i1] == wr_key)) begin
                wr_hit = 1'b1;
                wr_slot = i1;
            end
            if (!in_use[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign wr_ready = (wr_hit || any_free);
    wire [2:0] target = wr_hit ? wr_slot : free_slot;
    wire do_ins = wr_valid && wr_ready;

    always @(posedge clk) begin
        if (rst || flush) begin
            in_use <= 8'd0;
        end else if (do_ins) begin
            in_use[target] <= 1'b1;
            addr_tag[target] <= wr_key;
            payload[target] <= wr_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lookup_hit[0] + lookup_hit[1] + lookup_hit[2] + lookup_hit[3] + lookup_hit[4] + lookup_hit[5] + lookup_hit[6] + lookup_hit[7] <= 4'd1);
endmodule

// A 2-entry lookup table of 16-bit keys and 8-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module tlb_table #(
    parameter KEY_W = 16,
    parameter VAL_W = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_valid,
    output wire             wr_ready,
    input  wire [KEY_W-1:0] wr_key,
    input  wire [VAL_W-1:0] wr_val,
