    output wire [VAL_W-1:0] rd_val
);
    localparam N = 2;

    reg [N-1:0] v_q;
    reg [KEY_W-1:0] key_q [0:N-1];
    reg [VAL_W-1:0] val_q [0:N-1];
    reg [0:0] victim;

    initial v_q = 2'd0;
    initial victim = 1'd0;

    // lookup: every entry compared at once
    reg [N-1:0] match_q;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            match_q[i0] = v_q[i0] && (key_q[i0] == rd_key);
            if (match_q[i0]) lk_val_r = val_q[i0];
        end
    end
    assign rd_hit = |match_q;
    assign rd_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg wr_hit, any_free;
    reg [0:0] wr_slot, free_slot;
    integer i1;
    always @(*) begin
        wr_hit = 1'b0;
        wr_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (v_q[i1] && (key_q[i1] == wr_key)) begin
                wr_hit = 1'b1;
                wr_slot = i1;
            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign wr_ready = 1'b1;
    wire [0:0] target = wr_hit ? wr_slot : (any_free ? free_slot : victim);
    wire do_ins = wr_valid && wr_ready;

    always @(posedge clk) begin
        if (rst) begin
            v_q <= 2'd0;
            victim <= 1'd0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= wr_key;
            val_q[target] <= wr_val;
            if (!wr_hit && !any_free) victim <= victim + 1'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (match_q[0] + match_q[1] <= 2'd1);
endmodule

