// A 32-slot queue of 64-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module evt_buffer #(
    parameter WIDTH = 64
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             enq_valid,
    output wire             enq_ready,
    input  wire [WIDTH-1:0] enq_data,
    output wire             deq_valid,
    input  wire             deq_ready,
    output wire [WIDTH-1:0] deq_data,
    output wire [5:0]       level
);
    localparam DEPTH = 32;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [31:0] slot_full;
    reg [5:0] wr_ptr;
    reg [5:0] rd_ptr;

    initial slot_full = 32'd0;
    initial wr_ptr = 6'd0;
    initial rd_ptr = 6'd0;

    assign enq_ready  = (wr_ptr != {~rd_ptr[5], rd_ptr[4:0]});
    assign deq_valid = (wr_ptr != rd_ptr);
    wire do_push = enq_valid && enq_ready;
    wire do_pop  = deq_valid && deq_ready;
    assign deq_data = mem[rd_ptr[4:0]];
    assign level = wr_ptr - rd_ptr;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr[4:0]] <= enq_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            slot_full <= 32'd0;
            wr_ptr <= 6'd0;
            rd_ptr <= 6'd0;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr[4:0]] <= 1'b1;
                wr_ptr <= wr_ptr + 6'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr[4:0]] <= 1'b0;
                rd_ptr <= rd_ptr + 6'd1;
            end
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert ((wr_ptr - rd_ptr) == slot_full[0] + slot_full[1] + slot_full[2] + slot_full[3] + slot_full[4] + slot_full[5] + slot_full[6] + slot_full[7] + slot_full[8] + slot_full[9] + slot_full[10] + slot_full[11] + slot_full[12] + slot_full[13] + slot_full[14] + slot_full[15] + slot_full[16] + slot_full[17] + slot_full[18] + slot_full[19] + slot_full[20] + slot_full[21] + slot_full[22] + slot_full[23] + slot_full[24] + slot_full[25] + slot_full[26] + slot_full[27] + slot_full[28] + slot_full[29] + slot_full[30] + slot_full[31]);
endmodule

