// A 2-entry lookup table of 16-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module route_cam #(
    parameter KEY_W = 16,
    parameter VAL_W = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
    input  wire [VAL_W-1:0] ins_val,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 2;

    reg [N-1:0] in_use;
    reg [KEY_W-1:0] addr_tag [0:N-1];
    reg [VAL_W-1:0] payload [0:N-1];
    reg [0:0] victim;

    initial in_use = 2'd0;
    initial victim = 1'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lookup_hit;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lookup_hit[i0] = in_use[i0] && (addr_tag[i0] == lk_key);
            if (lookup_hit[i0]) lk_val_r = payload[i0];
        end
    end
    assign lk_hit = |lookup_hit;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [0:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (in_use[i1] && (addr_tag[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!in_use[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign ins_ready = 1'b1;
    wire [0:0] target = ins_hit ? ins_slot : (any_free ? free_slot : victim);
    wire do_ins = ins_valid && ins_ready;

    always @(posedge clk) begin
        if (rst) begin
            in_use <= 2'd0;
            victim <= 1'd0;
        end else if (do_ins) begin
            in_use[target] <= 1'b1;
            addr_tag[target] <= ins_key;
            payload[target] <= ins_val;
            if (!ins_hit && !any_free) victim <= victim + 1'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lookup_hit[0] + lookup_hit[1] <= 2'd1);
endmodule

