);
    localparam DEPTH = 8;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [7:0] slot_full;
    reg [2:0] wr_ptr;
    reg [2:0] rd_ptr;
    reg [3:0] count;

    initial slot_full = 8'd0;
    initial wr_ptr = 3'd0;
