    assign m_axis_tdata = mem[rd_ptr];
    assign level = count;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr] <= s_axis_tdata;
    end

    always @(posedge clk) begin
        if (rst) begin
            slot_full <= 8'd0;
            wr_ptr <= 3'd0;
            rd_ptr <= 3'd0;
            count <= 4'd0;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr] <= 1'b1;
                wr_ptr <= wr_ptr + 3'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr] <= 1'b0;
                rd_ptr <= rd_ptr + 3'd1;
            end
            if (do_push && !do_pop)
                count <= count + 4'd1;
            else if (do_pop && !do_push)
                count <= count - 4'd1;
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert (count == slot_full[0] + slot_full[1] + slot_full[2] + slot_full[3] + slot_full[4] + slot_full[5] + slot_full[6] + slot_full[7]);
endmodule

// A 8-entry lookup table of 4-bit keys and 8-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module tlb_table #(
    parameter KEY_W = 4,
    parameter VAL_W = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
    input  wire             drop_valid,
    input  wire [KEY_W-1:0] drop_key,
    input  wire [KEY_W-1:0] lookup_key,
    output wire             lookup_hit,
    output wire [VAL_W-1:0] lookup_val
);
    localparam N = 8;

    reg [N-1:0] valid;
    reg [KEY_W-1:0] keys [0:N-1];
    reg [VAL_W-1:0] vals [0:N-1];
    reg [2:0] victim;

    initial valid = 8'd0;
    initial victim = 3'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lk_match;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lk_match[i0] = valid[i0] && (keys[i0] == lookup_key);
            if (lk_match[i0]) lk_val_r = vals[i0];
        end
    end
    assign lookup_hit = |lk_match;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [2:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 3'd0;
        any_free = 1'b0;
        free_slot = 3'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (valid[i1] && (keys[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg drop_hit;
    reg [2:0] drop_slot;
    integer i2;
    always @(*) begin
        drop_hit = 1'b0;
        drop_slot = 3'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (valid[i2] && (keys[i2] == drop_key)) begin
                drop_hit = 1'b1;
                drop_slot = i2;
            end
    end

    assign fill_ready = !drop_valid;
    wire [2:0] target = fill_hit ? fill_slot : (any_free ? free_slot : victim);
    wire do_ins = fill_valid && fill_ready;
    wire do_inv = drop_valid && drop_hit;

    always @(posedge clk) begin
        if (rst) begin
            valid <= 8'd0;
            victim <= 3'd0;
        end else if (do_inv) begin
            valid[drop_slot] <= 1'b0;
        end else if (do_ins) begin
            valid[target] <= 1'b1;
            keys[target] <= fill_key;
            vals[target] <= fill_val;
            if (!fill_hit && !any_free) victim <= victim + 3'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lk_match[0] + lk_match[1] + lk_match[2] + lk_match[3] + lk_match[4] + lk_match[5] + lk_match[6] + lk_match[7] <= 4'd1);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module phys_reg_pool (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    output wire             alloc_valid,
    input  wire             alloc_ready,
    output wire [1:0]       alloc_id,
    input  wire             rel_valid,
    input  wire [1:0]       rel_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] taken;
    reg [1:0] pool_q [0:N-1];
    reg [1:0] head;
    reg [1:0] tail;
    reg [2:0] avail;

    initial taken = 4'd0;
    initial head = 2'd0;
    initial tail = 2'd0;
    initial avail = 3'd4;
    initial pool_q[0] = 2'd0;
    initial pool_q[1] = 2'd1;
    initial pool_q[2] = 2'd2;
    initial pool_q[3] = 2'd3;

    assign alloc_valid = (avail != 3'd0);
    assign alloc_id = pool_q[head];
    assign free_count = avail;
    wire do_alloc = alloc_valid && alloc_ready;
    wire do_rel = rel_valid && taken[rel_id];

    always @(posedge clk) begin
        if (rst || flush) begin
            taken <= 4'd0;
            head <= 2'd0;
            tail <= 2'd0;
            avail <= 3'd4;
            pool_q[0] <= 2'd0;
            pool_q[1] <= 2'd1;
            pool_q[2] <= 2'd2;
            pool_q[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                taken[pool_q[head]] <= 1'b1;
                head <= head + 2'd1;
            end
            if (do_rel) begin
                taken[rel_id] <= 1'b0;
                pool_q[tail] <= rel_id;
                tail <= tail + 2'd1;
            end
            if (do_alloc && !do_rel)
                avail <= avail - 3'd1;
            else if (do_rel && !do_alloc)
                avail <= avail + 3'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (avail + taken[0] + taken[1] + taken[2] + taken[3] == 3'd4);
endmodule

// A 4-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module msg_buffer #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [2:0]       level
);
    localparam DEPTH = 4;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [3:0] valid_q;
    reg [1:0] wptr_q;
    reg [1:0] rptr_q;
    reg [2:0] cnt_q;
    reg full_r, empty_r;

    initial valid_q = 4'd0;
    initial wptr_q = 2'd0;
    initial rptr_q = 2'd0;
    initial cnt_q = 3'd0;
    initial full_r = 1'b0;
    initial empty_r = 1'b1;

    assign full  = full_r;
    assign empty = empty_r;
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = ram[rptr_q];
    assign level = cnt_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q] <= push_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid_q <= 4'd0;
            wptr_q <= 2'd0;
            rptr_q <= 2'd0;
            cnt_q <= 3'd0;
            full_r <= 1'b0;
            empty_r <= 1'b1;
        end else begin
            if (do_push) begin
                valid_q[wptr_q] <= 1'b1;
                wptr_q <= wptr_q + 2'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q] <= 1'b0;
                rptr_q <= rptr_q + 2'd1;
            end
            if (do_push && !do_pop) begin
                cnt_q <= cnt_q + 3'd1;
                full_r <= (cnt_q == 3'd3);
                empty_r <= 1'b0;
            end else if (do_pop && !do_push) begin
                cnt_q <= cnt_q - 3'd1;
                full_r <= 1'b0;
                empty_r <= (cnt_q == 3'd1);
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !valid_q[wptr_q]);
endmodule

