// A 2-entry lookup table of 8-bit keys and 8-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module btb_cache #(
    parameter KEY_W = 8,
    parameter VAL_W = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
    input  wire [VAL_W-1:0] ins_val,
    input  wire             inv_valid,
    input  wire [KEY_W-1:0] inv_key,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 2;

    reg [N-1:0] entry_valid;
    reg [KEY_W-1:0] tag_q [0:N-1];
    reg [VAL_W-1:0] data_q [0:N-1];

    initial entry_valid = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] hit_vec;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            hit_vec[i0] = entry_valid[i0] && (tag_q[i0] == lk_key);
            if (hit_vec[i0]) lk_val_r = data_q[i0];
        end
    end
    assign lk_hit = |hit_vec;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [0:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (entry_valid[i1] && (tag_q[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!entry_valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg inv_hit;
    reg [0:0] inv_slot;
    integer i2;
    always @(*) begin
        inv_hit = 1'b0;
        inv_slot = 1'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (entry_valid[i2] && (tag_q[i2] == inv_key)) begin
                inv_hit = 1'b1;
                inv_slot = i2;
            end
    end

    assign ins_ready = (ins_hit || any_free) && !inv_valid;
    wire [0:0] target = ins_hit ? ins_slot : free_slot;
    wire do_ins = ins_valid && ins_ready;
    wire do_inv = inv_valid && inv_hit;

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 2'd0;
        end else if (do_inv) begin
            entry_valid[inv_slot] <= 1'b0;
        end else if (do_ins) begin
            entry_valid[target] <= 1'b1;
            tag_q[target] <= ins_key;
            data_q[target] <= ins_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (hit_vec[0] + hit_vec[1] <= 2'd1);
endmodule

// A 4-entry lookup table of 8-bit keys and 4-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module addr_cache #(
    parameter KEY_W = 8,
    parameter VAL_W = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_valid,
    output wire             wr_ready,
    input  wire [KEY_W-1:0] wr_key,
    input  wire [VAL_W-1:0] wr_val,
    input  wire [KEY_W-1:0] rd_key,
    output wire             rd_hit,
    output wire [VAL_W-1:0] rd_val
);
    localparam N = 4;

    reg [N-1:0] in_use;
    reg [KEY_W-1:0] addr_tag [0:N-1];
    reg [VAL_W-1:0] payload [0:N-1];

    initial in_use = 4'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lookup_hit;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lookup_hit[i0] = in_use[i0] && (addr_tag[i0] == rd_key);
            if (lookup_hit[i0]) lk_val_r = payload[i0];
        end
    end
    assign rd_hit = |lookup_hit;
    assign rd_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg wr_hit, any_free;
    reg [1:0] wr_slot, free_slot;
    integer i1;
    always @(*) begin
        wr_hit = 1'b0;
        wr_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (in_use[i1] && (addr_tag[i1] == wr_key)) begin
                wr_hit = 1'b1;
                wr_slot = i1;
            end
            if (!in_use[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign wr_ready = (wr_hit || any_free);
    wire [1:0] target = wr_hit ? wr_slot : free_slot;
    wire do_ins = wr_valid && wr_ready;

    always @(posedge clk) begin
        if (rst) begin
            in_use <= 4'd0;
        end else if (do_ins) begin
            in_use[target] <= 1'b1;
            addr_tag[target] <= wr_key;
            payload[target] <= wr_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lookup_hit[0] + lookup_hit[1] + lookup_hit[2] + lookup_hit[3] <= 3'd1);
endmodule

// A 16-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module evt_queue #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
