);
    localparam DEPTH = 16;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [15:0] occupied;
    reg [3:0] tail;
    reg [3:0] head;
    reg [4:0] fill;
    reg is_full, is_empty;

    initial occupied = 16'd0;
    initial tail = 4'd0;
    initial head = 4'd0;
    initial fill = 5'd0;
    initial is_full = 1'b0;
    initial is_empty = 1'b1;

    assign full  = is_full;
    assign empty = is_empty;
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= push_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            occupied <= 16'd0;
            tail <= 4'd0;
            head <= 4'd0;
            fill <= 5'd0;
            is_full <= 1'b0;
            is_empty <= 1'b1;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 4'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 4'd1;
            end
            if (do_push && !do_pop) begin
                fill <= fill + 5'd1;
                is_full <= (fill == 5'd15);
                is_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                fill <= fill - 5'd1;
                is_full <= 1'b0;
                is_empty <= (fill == 5'd1);
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !occupied[tail]);
endmodule

// A 4-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module pkt_buffer #(
    parameter WIDTH = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             s_axis_tvalid,
    output wire             s_axis_tready,
    input  wire [WIDTH-1:0] s_axis_tdata,
    output wire             m_axis_tvalid,
    input  wire             m_axis_tready,
    output wire [WIDTH-1:0] m_axis_tdata,
    output wire [2:0]       level
);
    localparam DEPTH = 4;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [3:0] valid_q;
    reg [1:0] wptr_q;
    reg [1:0] rptr_q;
