    reg full_r, empty_r;

    initial valid_q = 4'd0;
    initial wptr_q = 2'd0;
    initial rptr_q = 2'd0;
    initial cnt_q = 3'd0;
    initial full_r = 1'b0;
    initial empty_r = 1'b1;

    assign s_axis_tready  = !full_r;
    assign m_axis_tvalid = !empty_r;
    wire do_push = s_axis_tvalid && s_axis_tready;
    wire do_pop  = m_axis_tvalid && m_axis_tready;
    assign m_axis_tdata = ram[rptr_q];
    assign level = cnt_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q] <= s_axis_tdata;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid_q <= 4'd0;
            wptr_q <= 2'd0;
            rptr_q <= 2'd0;
            cnt_q <= 3'd0;
            full_r <= 1'b0;
            empty_r <= 1'b1;
        end else begin
            if (do_push) begin
                valid_q[wptr_q] <= 1'b1;
                wptr_q <= wptr_q + 2'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q] <= 1'b0;
                rptr_q <= rptr_q + 2'd1;
            end
            if (do_push && !do_pop) begin
                cnt_q <= cnt_q + 3'd1;
                full_r <= (cnt_q == 3'd3);
                empty_r <= 1'b0;
            end else if (do_pop && !do_push) begin
                cnt_q <= cnt_q - 3'd1;
                full_r <= 1'b0;
                empty_r <= (cnt_q == 3'd1);
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (!s_axis_tready || !valid_q[wptr_q]);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module slot_allocator (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    output wire             alloc_valid,
    input  wire             alloc_ready,
    output wire [1:0]       alloc_id,
    input  wire             rel_valid,
    input  wire [1:0]       rel_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] busy;
    reg [1:0] free_list [0:N-1];
    reg [1:0] fl_head;
    reg [1:0] fl_tail;
    reg [2:0] fl_count;

    initial busy = 4'd0;
    initial fl_head = 2'd0;
    initial fl_tail = 2'd0;
    initial fl_count = 3'd4;
    initial free_list[0] = 2'd0;
    initial free_list[1] = 2'd1;
    initial free_list[2] = 2'd2;
    initial free_list[3] = 2'd3;

    assign alloc_valid = (fl_count != 3'd0);
    assign alloc_id = free_list[fl_head];
    assign free_count = fl_count;
    wire do_alloc = alloc_valid && alloc_ready;
    wire do_rel = rel_valid && busy[rel_id];

    always @(posedge clk) begin
        if (rst || flush) begin
            busy <= 4'd0;
            fl_head <= 2'd0;
            fl_tail <= 2'd0;
            fl_count <= 3'd4;
            free_list[0] <= 2'd0;
            free_list[1] <= 2'd1;
            free_list[2] <= 2'd2;
            free_list[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                busy[free_list[fl_head]] <= 1'b1;
                fl_head <= fl_head + 2'd1;
            end
            if (do_rel) begin
                busy[rel_id] <= 1'b0;
                free_list[fl_tail] <= rel_id;
                fl_tail <= fl_tail + 2'd1;
            end
            if (do_alloc && !do_rel)
                fl_count <= fl_count - 3'd1;
            else if (do_rel && !do_alloc)
                fl_count <= fl_count + 3'd1;
        end
    end

    // an ID on offer is never in use
    always @(posedge clk) assert (!alloc_valid || !busy[alloc_id]);
endmodule

// A 4-entry lookup table of 16-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module tlb_cache #(
    parameter KEY_W = 16,
    parameter VAL_W = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
    input  wire [KEY_W-1:0] lookup_key,
    output wire             lookup_hit,
    output wire [VAL_W-1:0] lookup_val
);
    localparam N = 4;

    reg [N-1:0] v_q;
    reg [KEY_W-1:0] key_q [0:N-1];
    reg [VAL_W-1:0] val_q [0:N-1];
    reg [1:0] victim;

    initial v_q = 4'd0;
    initial victim = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] match_q;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            match_q[i0] = v_q[i0] && (key_q[i0] == lookup_key);
            if (match_q[i0]) lk_val_r = val_q[i0];
        end
    end
    assign lookup_hit = |match_q;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [1:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (v_q[i1] && (key_q[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign fill_ready = 1'b1;
    wire [1:0] target = fill_hit ? fill_slot : (any_free ? free_slot : victim);
    wire do_ins = fill_valid && fill_ready;

    always @(posedge clk) begin
        if (rst) begin
            v_q <= 4'd0;
            victim <= 2'd0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= fill_key;
            val_q[target] <= fill_val;
            if (!fill_hit && !any_free) victim <= victim + 2'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (match_q[0] + match_q[1] + match_q[2] + match_q[3] <= 3'd1);
endmodule

// A 2-slot queue of 4-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module pkt_queue #(
    parameter WIDTH = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [1:0]       level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [1:0] valid_q;
    reg [0:0] wptr_q;
    reg [0:0] rptr_q;
    reg [1:0] cnt_q;
    reg full_r, empty_r;

    initial valid_q = 2'd0;
    initial wptr_q = 1'd0;
    initial rptr_q = 1'd0;
    initial cnt_q = 2'd0;
    initial full_r = 1'b0;
    initial empty_r = 1'b1;

    assign full  = full_r;
    assign empty = empty_r;
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = ram[rptr_q];
    assign level = cnt_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q] <= push_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid_q <= 2'd0;
            wptr_q <= 1'd0;
            rptr_q <= 1'd0;
            cnt_q <= 2'd0;
            full_r <= 1'b0;
            empty_r <= 1'b1;
        end else begin
            if (do_push) begin
                valid_q[wptr_q] <= 1'b1;
                wptr_q <= wptr_q + 1'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q] <= 1'b0;
                rptr_q <= rptr_q + 1'd1;
            end
            if (do_push && !do_pop) begin
                cnt_q <= cnt_q + 2'd1;
                full_r <= (cnt_q == 2'd1);
                empty_r <= 1'b0;
            end else if (do_pop && !do_push) begin
                cnt_q <= cnt_q - 2'd1;
                full_r <= 1'b0;
                empty_r <= (cnt_q == 2'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (empty || valid_q[rptr_q]);
endmodule

// A 2-entry lookup table of 16-bit keys and 32-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module id_cam #(
    parameter KEY_W = 16,
    parameter VAL_W = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
    input  wire             drop_valid,
    input  wire [KEY_W-1:0] drop_key,
    input  wire [KEY_W-1:0] lookup_key,
    output wire             lookup_hit,
    output wire [VAL_W-1:0] lookup_val
);
    localparam N = 2;

    reg [N-1:0] valid;
    reg [KEY_W-1:0] keys [0:N-1];
    reg [VAL_W-1:0] vals [0:N-1];
    reg [0:0] victim;

    initial valid = 2'd0;
    initial victim = 1'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lk_match;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lk_match[i0] = valid[i0] && (keys[i0] == lookup_key);
            if (lk_match[i0]) lk_val_r = vals[i0];
        end
    end
    assign lookup_hit = |lk_match;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [0:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (valid[i1] && (keys[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg drop_hit;
    reg [0:0] drop_slot;
    integer i2;
    always @(*) begin
        drop_hit = 1'b0;
        drop_slot = 1'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (valid[i2] && (keys[i2] == drop_key)) begin
                drop_hit = 1'b1;
                drop_slot = i2;
            end
    end

    assign fill_ready = !drop_valid;
    wire [0:0] target = fill_hit ? fill_slot : (any_free ? free_slot : victim);
    wire do_ins = fill_valid && fill_ready;
    wire do_inv = drop_valid && drop_hit;

    always @(posedge clk) begin
        if (rst) begin
            valid <= 2'd0;
            victim <= 1'd0;
        end else if (do_inv) begin
            valid[drop_slot] <= 1'b0;
        end else if (do_ins) begin
            valid[target] <= 1'b1;
            keys[target] <= fill_key;
            vals[target] <= fill_val;
            if (!fill_hit && !any_free) victim <= victim + 1'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lk_match[0] + lk_match[1] <= 2'd1);
endmodule

// A 8-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module tx_queue #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             in_valid,
    output wire             in_ready,
    input  wire [WIDTH-1:0] in_data,
    output wire             out_valid,
    input  wire             out_ready,
    output wire [WIDTH-1:0] out_data,
    output wire [3:0]       level
);
    localparam DEPTH = 8;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [7:0] slot_full;
    reg [3:0] wr_ptr;
    reg [3:0] rd_ptr;

    initial slot_full = 8'd0;
    initial wr_ptr = 4'd0;
    initial rd_ptr = 4'd0;

    assign in_ready  = (wr_ptr != {~rd_ptr[3], rd_ptr[2:0]});
    assign out_valid = (wr_ptr != rd_ptr);
    wire do_push = in_valid && in_ready;
    wire do_pop  = out_valid && out_ready;
    assign out_data = mem[rd_ptr[2:0]];
    assign level = wr_ptr - rd_ptr;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr[2:0]] <= in_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            slot_full <= 8'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr[2:0]] <= 1'b1;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr[2:0]] <= 1'b0;
                rd_ptr <= rd_ptr + 4'd1;
            end
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert ((wr_ptr - rd_ptr) == slot_full[0] + slot_full[1] + slot_full[2] + slot_full[3] + slot_full[4] + slot_full[5] + slot_full[6] + slot_full[7]);
endmodule

// A 8-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module msg_queue #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             enq_valid,
    output wire             enq_ready,
    input  wire [WIDTH-1:0] enq_data,
    output wire             deq_valid,
    input  wire             deq_ready,
    output wire [WIDTH-1:0] deq_data,
    output wire [3:0]       fill_level
);
    localparam DEPTH = 8;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [7:0] occupied;
    reg [2:0] tail;
    reg [2:0] head;
    reg [3:0] fill;
    reg is_full, is_empty;

    initial occupied = 8'd0;
    initial tail = 3'd0;
    initial head = 3'd0;
    initial fill = 4'd0;
    initial is_full = 1'b0;
    initial is_empty = 1'b1;

    assign enq_ready  = !is_full;
    assign deq_valid = !is_empty;
    wire do_push = enq_valid && enq_ready;
    wire do_pop  = deq_valid && deq_ready;
    assign deq_data = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= enq_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            occupied <= 8'd0;
            tail <= 3'd0;
            head <= 3'd0;
            fill <= 4'd0;
            is_full <= 1'b0;
            is_empty <= 1'b1;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 3'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 3'd1;
            end
            if (do_push && !do_pop) begin
                fill <= fill + 4'd1;
                is_full <= (fill == 4'd7);
                is_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                fill <= fill - 4'd1;
                is_full <= 1'b0;
                is_empty <= (fill == 4'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (!deq_valid || occupied[head]);
endmodule

// A 32-slot queue of 32-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module msg_fifo #(
    parameter WIDTH = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [5:0]       occupancy
);
    localparam DEPTH = 32;

    reg [WIDTH-1:0] entries [0:DEPTH-1];
    reg [31:0] entry_valid;
    reg [5:0] waddr;
    reg [5:0] raddr;

    initial entry_valid = 32'd0;
    initial waddr = 6'd0;
    initial raddr = 6'd0;

    assign full  = (waddr == {~raddr[5], raddr[4:0]});
    assign empty = (waddr == raddr);
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = entries[raddr[4:0]];
    assign occupancy = waddr - raddr;

    always @(posedge clk) begin
        if (do_push) entries[waddr[4:0]] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            entry_valid <= 32'd0;
            waddr <= 6'd0;
            raddr <= 6'd0;
        end else begin
            if (do_push) begin
                entry_valid[waddr[4:0]] <= 1'b1;
                waddr <= waddr + 6'd1;
            end
            if (do_pop) begin
                entry_valid[raddr[4:0]] <= 1'b0;
                raddr <= raddr + 6'd1;
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !entry_valid[waddr[4:0]]);
endmodule

// A 2-entry lookup table of 32-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module route_map #(
    parameter KEY_W = 32,
    parameter VAL_W = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
    input  wire [VAL_W-1:0] ins_val,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 2;

    reg [N-1:0] entry_valid;
    reg [KEY_W-1:0] tag_q [0:N-1];
    reg [VAL_W-1:0] data_q [0:N-1];

    initial entry_valid = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] hit_vec;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            hit_vec[i0] = entry_valid[i0] && (tag_q[i0] == lk_key);
            if (hit_vec[i0]) lk_val_r = data_q[i0];
        end
    end
    assign lk_hit = |hit_vec;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [0:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (entry_valid[i1] && (tag_q[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!entry_valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign ins_ready = (ins_hit || any_free);
    wire [0:0] target = ins_hit ? ins_slot : free_slot;
    wire do_ins = ins_valid && ins_ready;

    always @(posedge clk) begin
        if (rst || flush) begin
            entry_valid <= 2'd0;
        end else if (do_ins) begin
            entry_valid[target] <= 1'b1;
            tag_q[target] <= ins_key;
            data_q[target] <= ins_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (hit_vec[0] + hit_vec[1] <= 2'd1);
endmodule

// A 32-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
