            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg drop_hit;
    reg [2:0] drop_slot;
    integer i2;
    always @(*) begin
        drop_hit = 1'b0;
        drop_slot = 3'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (v_q[i2] && (key_q[i2] == drop_key)) begin
                drop_hit = 1'b1;
                drop_slot = i2;
            end
    end

    assign fill_ready = !drop_valid;
    wire [2:0] target = fill_hit ? fill_slot : (any_free ? free_slot : victim);
    wire do_ins = fill_valid && fill_ready;
    wire do_inv = drop_valid && drop_hit;

    always @(posedge clk) begin
        if (rst || flush) begin
            v_q <= 8'd0;
            victim <= 3'd0;
        end else if (do_inv) begin
            v_q[drop_slot] <= 1'b0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= fill_key;
            val_q[target] <= fill_val;
            if (!fill_hit && !any_free) victim <= victim + 3'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (match_q[0] + match_q[1] + match_q[2] + match_q[3] + match_q[4] + match_q[5] + match_q[6] + match_q[7] <= 4'd1);
endmodule

// A 4-entry lookup table of 4-bit keys and 32-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module btb_cache #(
    parameter KEY_W = 4,
    parameter VAL_W = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_valid,
    output wire             wr_ready,
    input  wire [KEY_W-1:0] wr_key,
    input  wire [VAL_W-1:0] wr_val,
    input  wire             del_valid,
    input  wire [KEY_W-1:0] del_key,
    input  wire [KEY_W-1:0] rd_key,
    output wire             rd_hit,
    output wire [VAL_W-1:0] rd_val
);
    localparam N = 4;

    reg [N-1:0] valid;
    reg [KEY_W-1:0] keys [0:N-1];
    reg [VAL_W-1:0] vals [0:N-1];

    initial valid = 4'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lk_match;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lk_match[i0] = valid[i0] && (keys[i0] == rd_key);
            if (lk_match[i0]) lk_val_r = vals[i0];
        end
    end
    assign rd_hit = |lk_match;
    assign rd_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg wr_hit, any_free;
    reg [1:0] wr_slot, free_slot;
    integer i1;
    always @(*) begin
        wr_hit = 1'b0;
        wr_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (valid[i1] && (keys[i1] == wr_key)) begin
                wr_hit = 1'b1;
                wr_slot = i1;
            end
            if (!valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg del_hit;
    reg [1:0] del_slot;
    integer i2;
    always @(*) begin
        del_hit = 1'b0;
        del_slot = 2'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (valid[i2] && (keys[i2] == del_key)) begin
                del_hit = 1'b1;
                del_slot = i2;
            end
    end

    assign wr_ready = (wr_hit || any_free) && !del_valid;
    wire [1:0] target = wr_hit ? wr_slot : free_slot;
    wire do_ins = wr_valid && wr_ready;
    wire do_inv = del_valid && del_hit;

    always @(posedge clk) begin
        if (rst) begin
            valid <= 4'd0;
        end else if (do_inv) begin
            valid[del_slot] <= 1'b0;
        end else if (do_ins) begin
            valid[target] <= 1'b1;
            keys[target] <= wr_key;
            vals[target] <= wr_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lk_match[0] + lk_match[1] + lk_match[2] + lk_match[3] <= 3'd1);
endmodule

// A pool of 8 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module rob_allocator (
    input  wire             clk,
    input  wire             rst,
    output wire             alloc_valid,
    input  wire             alloc_ready,
    output wire [2:0]       alloc_id,
    input  wire             rel_valid,
    input  wire [2:0]       rel_id,
    output wire [3:0]       free_count
);
    localparam N = 8;

    reg [N-1:0] busy;
    reg [2:0] free_list [0:N-1];
    reg [2:0] fl_head;
    reg [2:0] fl_tail;
    reg [3:0] fl_count;

    initial busy = 8'd0;
    initial fl_head = 3'd0;
    initial fl_tail = 3'd0;
    initial fl_count = 4'd8;
    initial free_list[0] = 3'd0;
    initial free_list[1] = 3'd1;
    initial free_list[2] = 3'd2;
    initial free_list[3] = 3'd3;
    initial free_list[4] = 3'd4;
    initial free_list[5] = 3'd5;
    initial free_list[6] = 3'd6;
    initial free_list[7] = 3'd7;

    assign alloc_valid = (fl_count != 4'd0);
    assign alloc_id = free_list[fl_head];
    assign free_count = fl_count;
    wire do_alloc = alloc_valid && alloc_ready;
    wire do_rel = rel_valid && busy[rel_id];

    always @(posedge clk) begin
        if (rst) begin
            busy <= 8'd0;
            fl_head <= 3'd0;
            fl_tail <= 3'd0;
            fl_count <= 4'd8;
            free_list[0] <= 3'd0;
            free_list[1] <= 3'd1;
            free_list[2] <= 3'd2;
            free_list[3] <= 3'd3;
            free_list[4] <= 3'd4;
            free_list[5] <= 3'd5;
            free_list[6] <= 3'd6;
            free_list[7] <= 3'd7;
        end else begin
            if (do_alloc) begin
                busy[free_list[fl_head]] <= 1'b1;
                fl_head <= fl_head + 3'd1;
            end
            if (do_rel) begin
                busy[rel_id] <= 1'b0;
                free_list[fl_tail] <= rel_id;
                fl_tail <= fl_tail + 3'd1;
            end
            if (do_alloc && !do_rel)
                fl_count <= fl_count - 4'd1;
            else if (do_rel && !do_alloc)
                fl_count <= fl_count + 4'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (fl_count + busy[0] + busy[1] + busy[2] + busy[3] + busy[4] + busy[5] + busy[6] + busy[7] == 4'd8);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module slot_allocator (
    input  wire             clk,
