);
    localparam N = 4;

    reg [N-1:0] taken;
    reg [1:0] pool_q [0:N-1];
    reg [1:0] head;
    reg [1:0] tail;
    reg [2:0] avail;

    initial taken = 4'd0;
    initial head = 2'd0;
    initial tail = 2'd0;
    initial avail = 3'd4;
    initial pool_q[0] = 2'd0;
    initial pool_q[1] = 2'd1;
    initial pool_q[2] = 2'd2;
    initial pool_q[3] = 2'd3;

    assign get_valid = (avail != 3'd0);
    assign get_id = pool_q[head];
    assign free_count = avail;
    wire do_alloc = get_valid && get_ready;
    wire do_rel = put_valid && taken[put_id];

    always @(posedge clk) begin
        if (rst) begin
            taken <= 4'd0;
            head <= 2'd0;
            tail <= 2'd0;
            avail <= 3'd4;
            pool_q[0] <= 2'd0;
            pool_q[1] <= 2'd1;
            pool_q[2] <= 2'd2;
            pool_q[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                taken[pool_q[head]] <= 1'b1;
                head <= head + 2'd1;
            end
            if (do_rel) begin
                taken[put_id] <= 1'b0;
                pool_q[tail] <= put_id;
                tail <= tail + 2'd1;
            end
            if (do_alloc && !do_rel)
                avail <= avail - 3'd1;
            else if (do_rel && !do_alloc)
                avail <= avail + 3'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (avail + taken[0] + taken[1] + taken[2] + taken[3] == 3'd4);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module rob_pool (
