// A 16-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full.
module tag_queue #(
    parameter WIDTH = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [4:0]       fill_level
);
    localparam DEPTH = 16;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [15:0] occupied;
    reg [3:0] tail;
    reg [3:0] head;
    reg [4:0] fill;

    initial occupied = 16'd0;
    initial tail = 4'd0;
    initial head = 4'd0;
    initial fill = 5'd0;

    assign full  = (fill == 5'd16);
    assign empty = (fill == 5'd0);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= push_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            occupied <= 16'd0;
            tail <= 4'd0;
            head <= 4'd0;
            fill <= 5'd0;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 4'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 4'd1;
            end
            if (do_push && !do_pop)
                fill <= fill + 5'd1;
            else if (do_pop && !do_push)
                fill <= fill - 5'd1;
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !occupied[tail]);
endmodule

// A 64-slot queue of 4-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module evt_queue #(
    parameter WIDTH = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [6:0]       fill_level
);
    localparam DEPTH = 64;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [63:0] occupied;
    reg [6:0] tail;
    reg [6:0] head;

    initial occupied = 64'd0;
    initial tail = 7'd0;
    initial head = 7'd0;

    assign full  = (tail == {~head[6], head[5:0]});
    assign empty = (tail == head);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = storage[head[5:0]];
    assign fill_level = tail - head;

    always @(posedge clk) begin
        if (do_push) storage[tail[5:0]] <= push_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            occupied <= 64'd0;
            tail <= 7'd0;
            head <= 7'd0;
        end else begin
            if (do_push) begin
                occupied[tail[5:0]] <= 1'b1;
                tail <= tail + 7'd1;
            end
            if (do_pop) begin
                occupied[head[5:0]] <= 1'b0;
                head <= head + 7'd1;
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (empty || occupied[head[5:0]]);
endmodule

// A 4-entry lookup table of 4-bit keys and 32-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module addr_cache #(
    parameter KEY_W = 4,
    parameter VAL_W = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
    input  wire [VAL_W-1:0] ins_val,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 4;

    reg [N-1:0] v_q;
    reg [KEY_W-1:0] key_q [0:N-1];
    reg [VAL_W-1:0] val_q [0:N-1];
    reg [1:0] victim;

    initial v_q = 4'd0;
    initial victim = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] match_q;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            match_q[i0] = v_q[i0] && (key_q[i0] == lk_key);
            if (match_q[i0]) lk_val_r = val_q[i0];
        end
    end
    assign lk_hit = |match_q;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [1:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (v_q[i1] && (key_q[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign ins_ready = 1'b1;
    wire [1:0] target = ins_hit ? ins_slot : (any_free ? free_slot : victim);
    wire do_ins = ins_valid && ins_ready;

    always @(posedge clk) begin
        if (rst) begin
            v_q <= 4'd0;
            victim <= 2'd0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= ins_key;
            val_q[target] <= ins_val;
            if (!ins_hit && !any_free) victim <= victim + 2'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (match_q[0] + match_q[1] + match_q[2] + match_q[3] <= 3'd1);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module mshr_pool (
