);
    localparam N = 4;

    reg [N-1:0] taken;
    reg [1:0] pool_q [0:N-1];
    reg [1:0] head;
    reg [1:0] tail;
    reg [2:0] avail;

    initial taken = 4'd0;
    initial head = 2'd0;
    initial tail = 2'd0;
    initial avail = 3'd4;
    initial pool_q[0] = 2'd0;
    initial pool_q[1] = 2'd1;
    initial pool_q[2] = 2'd2;
    initial pool_q[3] = 2'd3;

    assign get_valid = (avail != 3'd0);
    assign get_id = pool_q[head];
    assign free_count = avail;
    wire do_alloc = get_valid && get_ready;
    wire do_rel = put_valid && taken[put_id];

    always @(posedge clk) begin
        if (rst) begin
            taken <= 4'd0;
            head <= 2'd0;
            tail <= 2'd0;
            avail <= 3'd4;
            pool_q[0] <= 2'd0;
            pool_q[1] <= 2'd1;
            pool_q[2] <= 2'd2;
            pool_q[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                taken[pool_q[head]] <= 1'b1;
                head <= head + 2'd1;
            end
            if (do_rel) begin
                taken[put_id] <= 1'b0;
                pool_q[tail] <= put_id;
                tail <= tail + 2'd1;
            end
            if (do_alloc && !do_rel)
                avail <= avail - 3'd1;
            else if (do_rel && !do_alloc)
                avail <= avail + 3'd1;
        end
    end

    // an ID on offer is never in use
    always @(posedge clk) assert (!get_valid || !taken[get_id]);
endmodule

// A 16-slot queue of 64-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module pkt_queue #(
    parameter WIDTH = 64
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [4:0]       occupancy
);
    localparam DEPTH = 16;

    reg [WIDTH-1:0] entries [0:DEPTH-1];
    reg [15:0] entry_valid;
    reg [3:0] waddr;
    reg [3:0] raddr;
    reg [4:0] used;
    reg r_full, r_empty;

    initial entry_valid = 16'd0;
    initial waddr = 4'd0;
    initial raddr = 4'd0;
    initial used = 5'd0;
    initial r_full = 1'b0;
    initial r_empty = 1'b1;

    assign full  = r_full;
    assign empty = r_empty;
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = entries[raddr];
    assign occupancy = used;

    always @(posedge clk) begin
        if (do_push) entries[waddr] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 16'd0;
            waddr <= 4'd0;
            raddr <= 4'd0;
            used <= 5'd0;
            r_full <= 1'b0;
            r_empty <= 1'b1;
        end else begin
            if (do_push) begin
                entry_valid[waddr] <= 1'b1;
                waddr <= waddr + 4'd1;
            end
            if (do_pop) begin
                entry_valid[raddr] <= 1'b0;
                raddr <= raddr + 4'd1;
            end
            if (do_push && !do_pop) begin
                used <= used + 5'd1;
                r_full <= (used == 5'd15);
                r_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                used <= used - 5'd1;
                r_full <= 1'b0;
                r_empty <= (used == 5'd1);
            end
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert (used == entry_valid[0] + entry_valid[1] + entry_valid[2] + entry_valid[3] + entry_valid[4] + entry_valid[5] + entry_valid[6] + entry_valid[7] + entry_valid[8] + entry_valid[9] + entry_valid[10] + entry_valid[11] + entry_valid[12] + entry_valid[13] + entry_valid[14] + entry_valid[15]);
endmodule

// A 32-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module cmd_buffer #(
    parameter WIDTH = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [5:0]       occupancy
);
    localparam DEPTH = 32;

    reg [WIDTH-1:0] entries [0:DEPTH-1];
    reg [31:0] entry_valid;
    reg [4:0] waddr;
    reg [4:0] raddr;
    reg [5:0] used;
    reg r_full, r_empty;

    initial entry_valid = 32'd0;
    initial waddr = 5'd0;
    initial raddr = 5'd0;
    initial used = 6'd0;
    initial r_full = 1'b0;
