        if (rst || flush) begin
            valid_q <= 2'd0;
            wptr_q <= 2'd0;
            rptr_q <= 2'd0;
        end else begin
            if (do_push) begin
                valid_q[wptr_q[0:0]] <= 1'b1;
                wptr_q <= wptr_q + 2'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q[0:0]] <= 1'b0;
                rptr_q <= rptr_q + 2'd1;
            end
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert ((wptr_q - rptr_q) == valid_q[0] + valid_q[1]);
endmodule

// A 4-entry lookup table of 16-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module btb_cam #(
    parameter KEY_W = 16,
    parameter VAL_W = 16
) (
