// A 2-slot queue of 64-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module req_queue #(
    parameter WIDTH = 64
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             enq_valid,
    output wire             enq_ready,
    input  wire [WIDTH-1:0] enq_data,
    output wire             deq_valid,
    input  wire             deq_ready,
    output wire [WIDTH-1:0] deq_data,
    output wire [1:0]       level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [1:0] valid_q;
    reg [0:0] wptr_q;
    reg [0:0] rptr_q;
    reg [1:0] cnt_q;
    reg full_r, empty_r;

    initial valid_q = 2'd0;
    initial wptr_q = 1'd0;
    initial rptr_q = 1'd0;
    initial cnt_q = 2'd0;
    initial full_r = 1'b0;
    initial empty_r = 1'b1;

    assign enq_ready  = !full_r;
    assign deq_valid = !empty_r;
    wire do_push = enq_valid && enq_ready;
    wire do_pop  = deq_valid && deq_ready;
    assign deq_data = ram[rptr_q];
    assign level = cnt_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q] <= enq_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid_q <= 2'd0;
            wptr_q <= 1'd0;
            rptr_q <= 1'd0;
            cnt_q <= 2'd0;
            full_r <= 1'b0;
            empty_r <= 1'b1;
        end else begin
            if (do_push) begin
                valid_q[wptr_q] <= 1'b1;
                wptr_q <= wptr_q + 1'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q] <= 1'b0;
                rptr_q <= rptr_q + 1'd1;
            end
            if (do_push && !do_pop) begin
                cnt_q <= cnt_q + 2'd1;
                full_r <= (cnt_q == 2'd1);
                empty_r <= 1'b0;
            end else if (do_pop && !do_push) begin
                cnt_q <= cnt_q - 2'd1;
                full_r <= 1'b0;
                empty_r <= (cnt_q == 2'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (!deq_valid || valid_q[rptr_q]);
endmodule

