    wire do_inv = del_valid && del_hit;

    always @(posedge clk) begin
        if (rst || flush) begin
            entry_valid <= 2'd0;
            victim <= 1'd0;
        end else if (do_inv) begin
            entry_valid[del_slot] <= 1'b0;
        end else if (do_ins) begin
            entry_valid[target] <= 1'b1;
