    always @(posedge clk) assert (hit_vec[0] + hit_vec[1] <= 2'd1);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module mshr_free_list (
    input  wire             clk,
    input  wire             rst,
    output wire             alloc_valid,
    input  wire             alloc_ready,
    output wire [1:0]       alloc_id,
    input  wire             rel_valid,
    input  wire [1:0]       rel_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] out_q;
    reg [1:0] spare [0:N-1];
    reg [1:0] get_ptr;
    reg [1:0] put_ptr;
    reg [2:0] n_free;

    initial out_q = 4'd0;
    initial get_ptr = 2'd0;
    initial put_ptr = 2'd0;
    initial n_free = 3'd4;
    initial spare[0] = 2'd0;
    initial spare[1] = 2'd1;
    initial spare[2] = 2'd2;
    initial spare[3] = 2'd3;

    assign alloc_valid = (n_free != 3'd0);
    assign alloc_id = spare[get_ptr];
    assign free_count = n_free;
    wire do_alloc = alloc_valid && alloc_ready;
    wire do_rel = rel_valid && out_q[rel_id];

    always @(posedge clk) begin
        if (rst) begin
            out_q <= 4'd0;
            get_ptr <= 2'd0;
            put_ptr <= 2'd0;
            n_free <= 3'd4;
            spare[0] <= 2'd0;
            spare[1] <= 2'd1;
            spare[2] <= 2'd2;
            spare[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                out_q[spare[get_ptr]] <= 1'b1;
                get_ptr <= get_ptr + 2'd1;
            end
            if (do_rel) begin
                out_q[rel_id] <= 1'b0;
                spare[put_ptr] <= rel_id;
                put_ptr <= put_ptr + 2'd1;
            end
            if (do_alloc && !do_rel)
                n_free <= n_free - 3'd1;
            else if (do_rel && !do_alloc)
                n_free <= n_free + 3'd1;
        end
    end

    // an ID on offer is never in use
    always @(posedge clk) assert (!alloc_valid || !out_q[alloc_id]);
endmodule

