            head <= 4'd0;
            fill <= 5'd0;
            is_full <= 1'b0;
            is_empty <= 1'b1;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 4'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 4'd1;
            end
            if (do_push && !do_pop) begin
                fill <= fill + 5'd1;
                is_full <= (fill == 5'd15);
                is_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                fill <= fill - 5'd1;
                is_full <= 1'b0;
                is_empty <= (fill == 5'd1);
            end
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert (fill == occupied[0] + occupied[1] + occupied[2] + occupied[3] + occupied[4] + occupied[5] + occupied[6] + occupied[7] + occupied[8] + occupied[9] + occupied[10] + occupied[11] + occupied[12] + occupied[13] + occupied[14] + occupied[15]);
endmodule

// A 8-entry lookup table of 32-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module addr_table #(
    parameter KEY_W = 32,
    parameter VAL_W = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
    input  wire             drop_valid,
    input  wire [KEY_W-1:0] drop_key,
    input  wire [KEY_W-1:0] lookup_key,
    output wire             lookup_hit,
    output wire [VAL_W-1:0] lookup_val
);
    localparam N = 8;

    reg [N-1:0] valid;
    reg [KEY_W-1:0] keys [0:N-1];
    reg [VAL_W-1:0] vals [0:N-1];

    initial valid = 8'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lk_match;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lk_match[i0] = valid[i0] && (keys[i0] == lookup_key);
            if (lk_match[i0]) lk_val_r = vals[i0];
        end
    end
    assign lookup_hit = |lk_match;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [2:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 3'd0;
        any_free = 1'b0;
        free_slot = 3'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (valid[i1] && (keys[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg drop_hit;
    reg [2:0] drop_slot;
    integer i2;
    always @(*) begin
        drop_hit = 1'b0;
        drop_slot = 3'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (valid[i2] && (keys[i2] == drop_key)) begin
                drop_hit = 1'b1;
                drop_slot = i2;
            end
    end

    assign fill_ready = (fill_hit || any_free) && !drop_valid;
    wire [2:0] target = fill_hit ? fill_slot : free_slot;
    wire do_ins = fill_valid && fill_ready;
    wire do_inv = drop_valid && drop_hit;

    always @(posedge clk) begin
        if (rst) begin
            valid <= 8'd0;
        end else if (do_inv) begin
            valid[drop_slot] <= 1'b0;
        end else if (do_ins) begin
            valid[target] <= 1'b1;
            keys[target] <= fill_key;
            vals[target] <= fill_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lk_match[0] + lk_match[1] + lk_match[2] + lk_match[3] + lk_match[4] + lk_match[5] + lk_match[6] + lk_match[7] <= 4'd1);
endmodule

