            end
            if (do_rel) begin
                out_q[put_id] <= 1'b0;
                spare[put_ptr] <= put_id;
                put_ptr <= put_ptr + 2'd1;
            end
            if (do_alloc && !do_rel)
                n_free <= n_free - 3'd1;
            else if (do_rel && !do_alloc)
                n_free <= n_free + 3'd1;
        end
    end

    // an ID on offer is never in use
    always @(posedge clk) assert (!get_valid || !out_q[get_id]);
endmodule

