// A 2-entry lookup table of 4-bit keys and 32-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module flow_map #(
    parameter KEY_W = 4,
    parameter VAL_W = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
