// A 4-slot queue of 4-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module tx_queue #(
    parameter WIDTH = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [2:0]       level
);
    localparam DEPTH = 4;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [3:0] valid_q;
    reg [2:0] wptr_q;
    reg [2:0] rptr_q;

    initial valid_q = 4'd0;
    initial wptr_q = 3'd0;
    initial rptr_q = 3'd0;

    assign full  = (wptr_q == {~rptr_q[2], rptr_q[1:0]});
    assign empty = (wptr_q == rptr_q);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = ram[rptr_q[1:0]];
    assign level = wptr_q - rptr_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q[1:0]] <= push_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid_q <= 4'd0;
            wptr_q <= 3'd0;
            rptr_q <= 3'd0;
        end else begin
            if (do_push) begin
                valid_q[wptr_q[1:0]] <= 1'b1;
                wptr_q <= wptr_q + 3'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q[1:0]] <= 1'b0;
                rptr_q <= rptr_q + 3'd1;
            end
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert ((wptr_q - rptr_q) == valid_q[0] + valid_q[1] + valid_q[2] + valid_q[3]);
endmodule

// A 4-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full.
module rx_fifo #(
    parameter WIDTH = 16
) (
