    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [2:0]       level
);
    localparam DEPTH = 4;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [3:0] valid_q;
    reg [1:0] wptr_q;
    reg [1:0] rptr_q;
    reg [2:0] cnt_q;

    initial valid_q = 4'd0;
    initial wptr_q = 2'd0;
    initial rptr_q = 2'd0;
    initial cnt_q = 3'd0;

    assign full  = (cnt_q == 3'd4);
    assign empty = (cnt_q == 3'd0);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = ram[rptr_q];
    assign level = cnt_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q] <= push_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            valid_q <= 4'd0;
            wptr_q <= 2'd0;
            rptr_q <= 2'd0;
            cnt_q <= 3'd0;
        end else begin
            if (do_push) begin
                valid_q[wptr_q] <= 1'b1;
                wptr_q <= wptr_q + 2'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q] <= 1'b0;
                rptr_q <= rptr_q + 2'd1;
            end
            if (do_push && !do_pop)
                cnt_q <= cnt_q + 3'd1;
            else if (do_pop && !do_push)
                cnt_q <= cnt_q - 3'd1;
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (empty || valid_q[rptr_q]);
endmodule

// A 2-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module pkt_fifo #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             s_axis_tvalid,
    output wire             s_axis_tready,
    input  wire [WIDTH-1:0] s_axis_tdata,
    output wire             m_axis_tvalid,
    input  wire             m_axis_tready,
    output wire [WIDTH-1:0] m_axis_tdata,
    output wire [1:0]       fill_level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [1:0] occupied;
    reg [1:0] tail;
    reg [1:0] head;

    initial occupied = 2'd0;
    initial tail = 2'd0;
    initial head = 2'd0;

    assign s_axis_tready  = (tail != {~head[1], head[0:0]});
    assign m_axis_tvalid = (tail != head);
    wire do_push = s_axis_tvalid && s_axis_tready;
    wire do_pop  = m_axis_tvalid && m_axis_tready;
    assign m_axis_tdata = storage[head[0:0]];
    assign fill_level = tail - head;

    always @(posedge clk) begin
        if (do_push) storage[tail[0:0]] <= s_axis_tdata;
    end

    always @(posedge clk) begin
        if (rst) begin
            occupied <= 2'd0;
            tail <= 2'd0;
            head <= 2'd0;
        end else begin
            if (do_push) begin
                occupied[tail[0:0]] <= 1'b1;
                tail <= tail + 2'd1;
            end
            if (do_pop) begin
                occupied[head[0:0]] <= 1'b0;
                head <= head + 2'd1;
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (!s_axis_tready || !occupied[tail[0:0]]);
endmodule

// A 2-entry lookup table of 32-bit keys and 32-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module btb_cam #(
    parameter KEY_W = 32,
    parameter VAL_W = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
    input  wire             drop_valid,
    input  wire [KEY_W-1:0] drop_key,
    input  wire [KEY_W-1:0] lookup_key,
    output wire             lookup_hit,
    output wire [VAL_W-1:0] lookup_val
);
    localparam N = 2;

    reg [N-1:0] entry_valid;
    reg [KEY_W-1:0] tag_q [0:N-1];
    reg [VAL_W-1:0] data_q [0:N-1];

    initial entry_valid = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] hit_vec;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            hit_vec[i0] = entry_valid[i0] && (tag_q[i0] == lookup_key);
            if (hit_vec[i0]) lk_val_r = data_q[i0];
        end
    end
    assign lookup_hit = |hit_vec;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [0:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (entry_valid[i1] && (tag_q[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!entry_valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg drop_hit;
    reg [0:0] drop_slot;
    integer i2;
    always @(*) begin
        drop_hit = 1'b0;
        drop_slot = 1'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (entry_valid[i2] && (tag_q[i2] == drop_key)) begin
                drop_hit = 1'b1;
                drop_slot = i2;
            end
    end

    assign fill_ready = (fill_hit || any_free) && !drop_valid;
    wire [0:0] target = fill_hit ? fill_slot : free_slot;
    wire do_ins = fill_valid && fill_ready;
    wire do_inv = drop_valid && drop_hit;

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 2'd0;
        end else if (do_inv) begin
            entry_valid[drop_slot] <= 1'b0;
        end else if (do_ins) begin
            entry_valid[target] <= 1'b1;
            tag_q[target] <= fill_key;
            data_q[target] <= fill_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (hit_vec[0] + hit_vec[1] <= 2'd1);
endmodule

// A 64-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full.
module pkt_fifo #(
    parameter WIDTH = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [6:0]       level
);
    localparam DEPTH = 64;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [63:0] valid_q;
    reg [5:0] wptr_q;
    reg [5:0] rptr_q;
    reg [6:0] cnt_q;

    initial valid_q = 64'd0;
    initial wptr_q = 6'd0;
    initial rptr_q = 6'd0;
    initial cnt_q = 7'd0;

    assign full  = (cnt_q == 7'd64);
    assign empty = (cnt_q == 7'd0);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = ram[rptr_q];
    assign level = cnt_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q] <= push_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid_q <= 64'd0;
            wptr_q <= 6'd0;
            rptr_q <= 6'd0;
            cnt_q <= 7'd0;
        end else begin
            if (do_push) begin
                valid_q[wptr_q] <= 1'b1;
                wptr_q <= wptr_q + 6'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q] <= 1'b0;
                rptr_q <= rptr_q + 6'd1;
            end
            if (do_push && !do_pop)
                cnt_q <= cnt_q + 7'd1;
            else if (do_pop && !do_push)
                cnt_q <= cnt_q - 7'd1;
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !valid_q[wptr_q]);
endmodule

