// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module tag_allocator (
    input  wire             clk,
    input  wire             rst,
    output wire             alloc_valid,
    input  wire             alloc_ready,
    output wire [1:0]       alloc_id,
    input  wire             rel_valid,
    input  wire [1:0]       rel_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] in_use;
    reg [1:0] free_ids [0:N-1];
    reg [1:0] rd_ptr;
    reg [1:0] wr_ptr;
    reg [2:0] num_free;

    initial in_use = 4'd0;
    initial rd_ptr = 2'd0;
    initial wr_ptr = 2'd0;
    initial num_free = 3'd4;
    initial free_ids[0] = 2'd0;
    initial free_ids[1] = 2'd1;
    initial free_ids[2] = 2'd2;
    initial free_ids[3] = 2'd3;

    assign alloc_valid = (num_free != 3'd0);
    assign alloc_id = free_ids[rd_ptr];
    assign free_count = num_free;
    wire do_alloc = alloc_valid && alloc_ready;
    wire do_rel = rel_valid && in_use[rel_id];

    always @(posedge clk) begin
        if (rst) begin
            in_use <= 4'd0;
            rd_ptr <= 2'd0;
            wr_ptr <= 2'd0;
            num_free <= 3'd4;
            free_ids[0] <= 2'd0;
            free_ids[1] <= 2'd1;
            free_ids[2] <= 2'd2;
            free_ids[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                in_use[free_ids[rd_ptr]] <= 1'b1;
                rd_ptr <= rd_ptr + 2'd1;
            end
            if (do_rel) begin
                in_use[rel_id] <= 1'b0;
                free_ids[wr_ptr] <= rel_id;
                wr_ptr <= wr_ptr + 2'd1;
            end
            if (do_alloc && !do_rel)
                num_free <= num_free - 3'd1;
            else if (do_rel && !do_alloc)
                num_free <= num_free + 3'd1;
        end
    end

    // an ID on offer is never in use
    always @(posedge clk) assert (!alloc_valid || !in_use[alloc_id]);
endmodule

