// A 2-slot queue of 64-bit items with a full bit per slot; the sender waits when it is full.
module cmd_fifo #(
    parameter WIDTH = 64
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [1:0]       fill_level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [1:0] occupied;
    reg [0:0] tail;
    reg [0:0] head;
    reg [1:0] fill;

    initial occupied = 2'd0;
    initial tail = 1'd0;
    initial head = 1'd0;
    initial fill = 2'd0;

    assign full  = (fill == 2'd2);
    assign empty = (fill == 2'd0);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= push_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            occupied <= 2'd0;
            tail <= 1'd0;
            head <= 1'd0;
            fill <= 2'd0;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 1'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 1'd1;
            end
            if (do_push && !do_pop)
                fill <= fill + 2'd1;
            else if (do_pop && !do_push)
                fill <= fill - 2'd1;
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !occupied[tail]);
endmodule

// A 32-slot queue of 64-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module msg_queue #(
    parameter WIDTH = 64
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [5:0]       occupancy
);
    localparam DEPTH = 32;

    reg [WIDTH-1:0] entries [0:DEPTH-1];
    reg [31:0] entry_valid;
    reg [4:0] waddr;
    reg [4:0] raddr;
    reg [5:0] used;
    reg r_full, r_empty;

    initial entry_valid = 32'd0;
    initial waddr = 5'd0;
    initial raddr = 5'd0;
    initial used = 6'd0;
    initial r_full = 1'b0;
    initial r_empty = 1'b1;

    assign full  = r_full;
    assign empty = r_empty;
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = entries[raddr];
    assign occupancy = used;

    always @(posedge clk) begin
        if (do_push) entries[waddr] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 32'd0;
            waddr <= 5'd0;
            raddr <= 5'd0;
            used <= 6'd0;
            r_full <= 1'b0;
            r_empty <= 1'b1;
        end else begin
            if (do_push) begin
                entry_valid[waddr] <= 1'b1;
                waddr <= waddr + 5'd1;
            end
            if (do_pop) begin
                entry_valid[raddr] <= 1'b0;
                raddr <= raddr + 5'd1;
            end
            if (do_push && !do_pop) begin
                used <= used + 6'd1;
                r_full <= (used == 6'd31);
                r_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                used <= used - 6'd1;
                r_full <= 1'b0;
                r_empty <= (used == 6'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (empty || entry_valid[raddr]);
endmodule

// A 4-entry lookup table of 8-bit keys and 4-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module btb_table #(
