) (
    input  wire             clk,
    input  wire             rst,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
    input  wire [VAL_W-1:0] ins_val,
    input  wire             inv_valid,
    input  wire [KEY_W-1:0] inv_key,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 4;

    reg [N-1:0] entry_valid;
    reg [KEY_W-1:0] tag_q [0:N-1];
    reg [VAL_W-1:0] data_q [0:N-1];
    reg [1:0] victim;

    initial entry_valid = 4'd0;
    initial victim = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] hit_vec;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            hit_vec[i0] = entry_valid[i0] && (tag_q[i0] == lk_key);
            if (hit_vec[i0]) lk_val_r = data_q[i0];
        end
    end
    assign lk_hit = |hit_vec;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [1:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (entry_valid[i1] && (tag_q[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!entry_valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg inv_hit;
    reg [1:0] inv_slot;
    integer i2;
    always @(*) begin
        inv_hit = 1'b0;
        inv_slot = 2'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (entry_valid[i2] && (tag_q[i2] == inv_key)) begin
                inv_hit = 1'b1;
                inv_slot = i2;
            end
    end

    assign ins_ready = !inv_valid;
    wire [1:0] target = ins_hit ? ins_slot : (any_free ? free_slot : victim);
    wire do_ins = ins_valid && ins_ready;
    wire do_inv = inv_valid && inv_hit;

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 4'd0;
            victim <= 2'd0;
        end else if (do_inv) begin
            entry_valid[inv_slot] <= 1'b0;
        end else if (do_ins) begin
            entry_valid[target] <= 1'b1;
            tag_q[target] <= ins_key;
            data_q[target] <= ins_val;
            if (!ins_hit && !any_free) victim <= victim + 2'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (hit_vec[0] + hit_vec[1] + hit_vec[2] + hit_vec[3] <= 3'd1);
endmodule

// A 64-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full.
module pkt_queue #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             enq_valid,
    output wire             enq_ready,
    input  wire [WIDTH-1:0] enq_data,
    output wire             deq_valid,
    input  wire             deq_ready,
    output wire [WIDTH-1:0] deq_data,
    output wire [6:0]       occupancy
);
    localparam DEPTH = 64;

    reg [WIDTH-1:0] entries [0:DEPTH-1];
    reg [63:0] entry_valid;
    reg [5:0] waddr;
    reg [5:0] raddr;
    reg [6:0] used;

    initial entry_valid = 64'd0;
    initial waddr = 6'd0;
    initial raddr = 6'd0;
    initial used = 7'd0;

    assign enq_ready  = (used != 7'd64);
    assign deq_valid = (used != 7'd0);
    wire do_push = enq_valid && enq_ready;
    wire do_pop  = deq_valid && deq_ready;
    assign deq_data = entries[raddr];
    assign occupancy = used;

    always @(posedge clk) begin
        if (do_push) entries[waddr] <= enq_data;
