    always @(posedge clk) begin
        if (rst || flush) begin
            entry_valid <= 64'd0;
            waddr <= 6'd0;
            raddr <= 6'd0;
            used <= 7'd0;
        end else begin
            if (do_push) begin
                entry_valid[waddr] <= 1'b1;
                waddr <= waddr + 6'd1;
            end
            if (do_pop) begin
                entry_valid[raddr] <= 1'b0;
                raddr <= raddr + 6'd1;
            end
            if (do_push && !do_pop)
                used <= used + 7'd1;
            else if (do_pop && !do_push)
                used <= used - 7'd1;
