    // the count equals the number of filled slots
    always @(posedge clk) assert (used == entry_valid[0] + entry_valid[1] + entry_valid[2] + entry_valid[3] + entry_valid[4] + entry_valid[5] + entry_valid[6] + entry_valid[7] + entry_valid[8] + entry_valid[9] + entry_valid[10] + entry_valid[11] + entry_valid[12] + entry_valid[13] + entry_valid[14] + entry_valid[15] + entry_valid[16] + entry_valid[17] + entry_valid[18] + entry_valid[19] + entry_valid[20] + entry_valid[21] + entry_valid[22] + entry_valid[23] + entry_valid[24] + entry_valid[25] + entry_valid[26] + entry_valid[27] + entry_valid[28] + entry_valid[29] + entry_valid[30] + entry_valid[31] + entry_valid[32] + entry_valid[33] + entry_valid[34] + entry_valid[35] + entry_valid[36] + entry_valid[37] + entry_valid[38] + entry_valid[39] + entry_valid[40] + entry_valid[41] + entry_valid[42] + entry_valid[43] + entry_valid[44] + entry_valid[45] + entry_valid[46] + entry_valid[47] + entry_valid[48] + entry_valid[49] + entry_valid[50] + entry_valid[51] + entry_valid[52] + entry_valid[53] + entry_valid[54] + entry_valid[55] + entry_valid[56] + entry_valid[57] + entry_valid[58] + entry_valid[59] + entry_valid[60] + entry_valid[61] + entry_valid[62] + entry_valid[63]);
endmodule

// A 4-entry lookup table of 12-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module flow_table #(
    parameter KEY_W = 12,
    parameter VAL_W = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_valid,
    output wire             wr_ready,
    input  wire [KEY_W-1:0] wr_key,
    input  wire [VAL_W-1:0] wr_val,
    input  wire [KEY_W-1:0] rd_key,
    output wire             rd_hit,
    output wire [VAL_W-1:0] rd_val
);
    localparam N = 4;

    reg [N-1:0] v_q;
    reg [KEY_W-1:0] key_q [0:N-1];
    reg [VAL_W-1:0] val_q [0:N-1];
    reg [1:0] victim;

    initial v_q = 4'd0;
    initial victim = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] match_q;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            match_q[i0] = v_q[i0] && (key_q[i0] == rd_key);
            if (match_q[i0]) lk_val_r = val_q[i0];
        end
    end
    assign rd_hit = |match_q;
    assign rd_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg wr_hit, any_free;
    reg [1:0] wr_slot, free_slot;
    integer i1;
    always @(*) begin
        wr_hit = 1'b0;
        wr_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (v_q[i1] && (key_q[i1] == wr_key)) begin
                wr_hit = 1'b1;
                wr_slot = i1;
            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign wr_ready = 1'b1;
    wire [1:0] target = wr_hit ? wr_slot : (any_free ? free_slot : victim);
    wire do_ins = wr_valid && wr_ready;

    always @(posedge clk) begin
        if (rst) begin
            v_q <= 4'd0;
            victim <= 2'd0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= wr_key;
            val_q[target] <= wr_val;
            if (!wr_hit && !any_free) victim <= victim + 2'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (match_q[0] + match_q[1] + match_q[2] + match_q[3] <= 3'd1);
endmodule

// A 32-slot queue of 4-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module tag_buffer #(
    parameter WIDTH = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [5:0]       level
);
    localparam DEPTH = 32;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [31:0] valid_q;
    reg [4:0] wptr_q;
    reg [4:0] rptr_q;
    reg [5:0] cnt_q;
    reg full_r, empty_r;

    initial valid_q = 32'd0;
    initial wptr_q = 5'd0;
    initial rptr_q = 5'd0;
    initial cnt_q = 6'd0;
    initial full_r = 1'b0;
    initial empty_r = 1'b1;

    assign full  = full_r;
    assign empty = empty_r;
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = ram[rptr_q];
    assign level = cnt_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q] <= push_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid_q <= 32'd0;
            wptr_q <= 5'd0;
            rptr_q <= 5'd0;
            cnt_q <= 6'd0;
            full_r <= 1'b0;
            empty_r <= 1'b1;
        end else begin
            if (do_push) begin
                valid_q[wptr_q] <= 1'b1;
                wptr_q <= wptr_q + 5'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q] <= 1'b0;
                rptr_q <= rptr_q + 5'd1;
            end
            if (do_push && !do_pop) begin
                cnt_q <= cnt_q + 6'd1;
                full_r <= (cnt_q == 6'd31);
                empty_r <= 1'b0;
            end else if (do_pop && !do_push) begin
                cnt_q <= cnt_q - 6'd1;
                full_r <= 1'b0;
                empty_r <= (cnt_q == 6'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (empty || valid_q[rptr_q]);
endmodule

// A 16-slot queue of 64-bit items with a full bit per slot; the sender waits when it is full.
module req_queue #(
    parameter WIDTH = 64
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [4:0]       level
);
    localparam DEPTH = 16;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [15:0] slot_full;
    reg [3:0] wr_ptr;
    reg [3:0] rd_ptr;
    reg [4:0] count;

    initial slot_full = 16'd0;
    initial wr_ptr = 4'd0;
    initial rd_ptr = 4'd0;
    initial count = 5'd0;

    assign full  = (count == 5'd16);
    assign empty = (count == 5'd0);
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = mem[rd_ptr];
    assign level = count;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            slot_full <= 16'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
            count <= 5'd0;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr] <= 1'b1;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr] <= 1'b0;
                rd_ptr <= rd_ptr + 4'd1;
            end
            if (do_push && !do_pop)
                count <= count + 5'd1;
            else if (do_pop && !do_push)
                count <= count - 5'd1;
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !slot_full[wr_ptr]);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module credit_allocator (
    input  wire             clk,
    input  wire             rst,
    output wire             get_valid,
    input  wire             get_ready,
    output wire [1:0]       get_id,
    input  wire             put_valid,
    input  wire [1:0]       put_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] busy;
    reg [1:0] free_list [0:N-1];
    reg [1:0] fl_head;
    reg [1:0] fl_tail;
    reg [2:0] fl_count;

    initial busy = 4'd0;
    initial fl_head = 2'd0;
    initial fl_tail = 2'd0;
    initial fl_count = 3'd4;
    initial free_list[0] = 2'd0;
    initial free_list[1] = 2'd1;
    initial free_list[2] = 2'd2;
    initial free_list[3] = 2'd3;

    assign get_valid = (fl_count != 3'd0);
    assign get_id = free_list[fl_head];
    assign free_count = fl_count;
    wire do_alloc = get_valid && get_ready;
    wire do_rel = put_valid && busy[put_id];

    always @(posedge clk) begin
        if (rst) begin
            busy <= 4'd0;
            fl_head <= 2'd0;
            fl_tail <= 2'd0;
            fl_count <= 3'd4;
            free_list[0] <= 2'd0;
            free_list[1] <= 2'd1;
            free_list[2] <= 2'd2;
            free_list[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                busy[free_list[fl_head]] <= 1'b1;
                fl_head <= fl_head + 2'd1;
            end
            if (do_rel) begin
                busy[put_id] <= 1'b0;
                free_list[fl_tail] <= put_id;
                fl_tail <= fl_tail + 2'd1;
            end
            if (do_alloc && !do_rel)
                fl_count <= fl_count - 3'd1;
            else if (do_rel && !do_alloc)
                fl_count <= fl_count + 3'd1;
        end
    end

    // an ID on offer is never in use
    always @(posedge clk) assert (!get_valid || !busy[get_id]);
endmodule

// A 32-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module desc_buffer #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [5:0]       level
);
    localparam DEPTH = 32;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [31:0] slot_full;
    reg [5:0] wr_ptr;
    reg [5:0] rd_ptr;

    initial slot_full = 32'd0;
    initial wr_ptr = 6'd0;
    initial rd_ptr = 6'd0;

    assign full  = (wr_ptr == {~rd_ptr[5], rd_ptr[4:0]});
    assign empty = (wr_ptr == rd_ptr);
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = mem[rd_ptr[4:0]];
    assign level = wr_ptr - rd_ptr;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr[4:0]] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            slot_full <= 32'd0;
            wr_ptr <= 6'd0;
            rd_ptr <= 6'd0;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr[4:0]] <= 1'b1;
                wr_ptr <= wr_ptr + 6'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr[4:0]] <= 1'b0;
                rd_ptr <= rd_ptr + 6'd1;
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (empty || slot_full[rd_ptr[4:0]]);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module rob_pool (
