    initial full_q = 1'b0;
    initial empty_q = 1'b1;

    assign full  = full_q;
    assign empty = empty_q;
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = mem[rd_ptr];
    assign level = count;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            slot_full <= 8'd0;
            wr_ptr <= 3'd0;
            rd_ptr <= 3'd0;
            count <= 4'd0;
            full_q <= 1'b0;
            empty_q <= 1'b1;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr] <= 1'b1;
                wr_ptr <= wr_ptr + 3'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr] <= 1'b0;
                rd_ptr <= rd_ptr + 3'd1;
            end
            if (do_push && !do_pop) begin
                count <= count + 4'd1;
                full_q <= (count == 4'd7);
                empty_q <= 1'b0;
            end else if (do_pop && !do_push) begin
                count <= count - 4'd1;
                full_q <= 1'b0;
                empty_q <= (count == 4'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (empty || slot_full[rd_ptr]);
endmodule

// A pool of 8 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module slot_pool (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    output wire             take_valid,
    input  wire             take_ready,
    output wire [2:0]       take_id,
    input  wire             give_valid,
    input  wire [2:0]       give_id,
    output wire [3:0]       free_count
);
    localparam N = 8;

    reg [N-1:0] in_use;
    reg [2:0] free_ids [0:N-1];
    reg [2:0] rd_ptr;
    reg [2:0] wr_ptr;
    reg [3:0] num_free;

    initial in_use = 8'd0;
    initial rd_ptr = 3'd0;
    initial wr_ptr = 3'd0;
    initial num_free = 4'd8;
    initial free_ids[0] = 3'd0;
    initial free_ids[1] = 3'd1;
    initial free_ids[2] = 3'd2;
    initial free_ids[3] = 3'd3;
    initial free_ids[4] = 3'd4;
    initial free_ids[5] = 3'd5;
    initial free_ids[6] = 3'd6;
    initial free_ids[7] = 3'd7;

    assign take_valid = (num_free != 4'd0);
    assign take_id = free_ids[rd_ptr];
    assign free_count = num_free;
    wire do_alloc = take_valid && take_ready;
    wire do_rel = give_valid && in_use[give_id];

    always @(posedge clk) begin
        if (rst || flush) begin
            in_use <= 8'd0;
            rd_ptr <= 3'd0;
            wr_ptr <= 3'd0;
            num_free <= 4'd8;
            free_ids[0] <= 3'd0;
            free_ids[1] <= 3'd1;
            free_ids[2] <= 3'd2;
            free_ids[3] <= 3'd3;
            free_ids[4] <= 3'd4;
            free_ids[5] <= 3'd5;
            free_ids[6] <= 3'd6;
            free_ids[7] <= 3'd7;
        end else begin
            if (do_alloc) begin
                in_use[free_ids[rd_ptr]] <= 1'b1;
                rd_ptr <= rd_ptr + 3'd1;
            end
            if (do_rel) begin
                in_use[give_id] <= 1'b0;
                free_ids[wr_ptr] <= give_id;
                wr_ptr <= wr_ptr + 3'd1;
            end
            if (do_alloc && !do_rel)
                num_free <= num_free - 4'd1;
            else if (do_rel && !do_alloc)
                num_free <= num_free + 4'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (num_free + in_use[0] + in_use[1] + in_use[2] + in_use[3] + in_use[4] + in_use[5] + in_use[6] + in_use[7] == 4'd8);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module slot_pool (
