        end else begin
            if (do_alloc) begin
                busy[free_list[fl_head]] <= 1'b1;
                fl_head <= fl_head + 2'd1;
            end
            if (do_rel) begin
                busy[rel_id] <= 1'b0;
                free_list[fl_tail] <= rel_id;
                fl_tail <= fl_tail + 2'd1;
            end
            if (do_alloc && !do_rel)
                fl_count <= fl_count - 3'd1;
            else if (do_rel && !do_alloc)
                fl_count <= fl_count + 3'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (fl_count + busy[0] + busy[1] + busy[2] + busy[3] == 3'd4);
endmodule

// A 8-entry lookup table of 16-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module session_cache #(
    parameter KEY_W = 16,
    parameter VAL_W = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
    input  wire             drop_valid,
    input  wire [KEY_W-1:0] drop_key,
    input  wire [KEY_W-1:0] lookup_key,
    output wire             lookup_hit,
    output wire [VAL_W-1:0] lookup_val
);
    localparam N = 8;

    reg [N-1:0] entry_valid;
    reg [KEY_W-1:0] tag_q [0:N-1];
    reg [VAL_W-1:0] data_q [0:N-1];
    reg [2:0] victim;

    initial entry_valid = 8'd0;
    initial victim = 3'd0;

    // lookup: every entry compared at once
    reg [N-1:0] hit_vec;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            hit_vec[i0] = entry_valid[i0] && (tag_q[i0] == lookup_key);
            if (hit_vec[i0]) lk_val_r = data_q[i0];
        end
    end
    assign lookup_hit = |hit_vec;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [2:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 3'd0;
        any_free = 1'b0;
        free_slot = 3'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (entry_valid[i1] && (tag_q[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!entry_valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg drop_hit;
    reg [2:0] drop_slot;
    integer i2;
    always @(*) begin
        drop_hit = 1'b0;
        drop_slot = 3'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (entry_valid[i2] && (tag_q[i2] == drop_key)) begin
                drop_hit = 1'b1;
                drop_slot = i2;
            end
    end

    assign fill_ready = !drop_valid;
    wire [2:0] target = fill_hit ? fill_slot : (any_free ? free_slot : victim);
    wire do_ins = fill_valid && fill_ready;
    wire do_inv = drop_valid && drop_hit;

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 8'd0;
            victim <= 3'd0;
        end else if (do_inv) begin
            entry_valid[drop_slot] <= 1'b0;
        end else if (do_ins) begin
            entry_valid[target] <= 1'b1;
            tag_q[target] <= fill_key;
            data_q[target] <= fill_val;
            if (!fill_hit && !any_free) victim <= victim + 3'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (hit_vec[0] + hit_vec[1] + hit_vec[2] + hit_vec[3] + hit_vec[4] + hit_vec[5] + hit_vec[6] + hit_vec[7] <= 4'd1);
endmodule

// A pool of 8 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module phys_reg_free_list (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    output wire             take_valid,
    input  wire             take_ready,
    output wire [2:0]       take_id,
    input  wire             give_valid,
    input  wire [2:0]       give_id,
    output wire [3:0]       free_count
);
    localparam N = 8;

    reg [N-1:0] taken;
    reg [2:0] pool_q [0:N-1];
    reg [2:0] head;
    reg [2:0] tail;
    reg [3:0] avail;

    initial taken = 8'd0;
    initial head = 3'd0;
    initial tail = 3'd0;
    initial avail = 4'd8;
    initial pool_q[0] = 3'd0;
    initial pool_q[1] = 3'd1;
    initial pool_q[2] = 3'd2;
    initial pool_q[3] = 3'd3;
    initial pool_q[4] = 3'd4;
    initial pool_q[5] = 3'd5;
    initial pool_q[6] = 3'd6;
    initial pool_q[7] = 3'd7;

    assign take_valid = (avail != 4'd0);
    assign take_id = pool_q[head];
    assign free_count = avail;
    wire do_alloc = take_valid && take_ready;
    wire do_rel = give_valid && taken[give_id];

    always @(posedge clk) begin
        if (rst || flush) begin
            taken <= 8'd0;
            head <= 3'd0;
            tail <= 3'd0;
            avail <= 4'd8;
            pool_q[0] <= 3'd0;
            pool_q[1] <= 3'd1;
            pool_q[2] <= 3'd2;
            pool_q[3] <= 3'd3;
            pool_q[4] <= 3'd4;
            pool_q[5] <= 3'd5;
            pool_q[6] <= 3'd6;
            pool_q[7] <= 3'd7;
        end else begin
            if (do_alloc) begin
                taken[pool_q[head]] <= 1'b1;
                head <= head + 3'd1;
            end
            if (do_rel) begin
                taken[give_id] <= 1'b0;
                pool_q[tail] <= give_id;
                tail <= tail + 3'd1;
            end
            if (do_alloc && !do_rel)
                avail <= avail - 4'd1;
            else if (do_rel && !do_alloc)
                avail <= avail + 4'd1;
        end
    end

    // an ID on offer is never in use
    always @(posedge clk) assert (!take_valid || !taken[take_id]);
endmodule

// A 2-entry lookup table of 16-bit keys and 4-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module btb_cam #(
    parameter KEY_W = 16,
    parameter VAL_W = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
    input  wire [KEY_W-1:0] lookup_key,
    output wire             lookup_hit,
    output wire [VAL_W-1:0] lookup_val
);
    localparam N = 2;

    reg [N-1:0] v_q;
    reg [KEY_W-1:0] key_q [0:N-1];
    reg [VAL_W-1:0] val_q [0:N-1];

    initial v_q = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] match_q;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            match_q[i0] = v_q[i0] && (key_q[i0] == lookup_key);
            if (match_q[i0]) lk_val_r = val_q[i0];
        end
    end
    assign lookup_hit = |match_q;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [0:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (v_q[i1] && (key_q[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign fill_ready = (fill_hit || any_free);
    wire [0:0] target = fill_hit ? fill_slot : free_slot;
    wire do_ins = fill_valid && fill_ready;

    always @(posedge clk) begin
        if (rst) begin
            v_q <= 2'd0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= fill_key;
            val_q[target] <= fill_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (match_q[0] + match_q[1] <= 2'd1);
endmodule

// A 2-slot queue of 8-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module evt_fifo #(
    parameter WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [1:0]       fill_level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [1:0] occupied;
    reg [0:0] tail;
    reg [0:0] head;
    reg [1:0] fill;
    reg is_full, is_empty;

    initial occupied = 2'd0;
    initial tail = 1'd0;
    initial head = 1'd0;
    initial fill = 2'd0;
    initial is_full = 1'b0;
    initial is_empty = 1'b1;

    assign full  = is_full;
    assign empty = is_empty;
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= push_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            occupied <= 2'd0;
            tail <= 1'd0;
            head <= 1'd0;
            fill <= 2'd0;
            is_full <= 1'b0;
            is_empty <= 1'b1;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 1'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 1'd1;
            end
            if (do_push && !do_pop) begin
                fill <= fill + 2'd1;
                is_full <= (fill == 2'd1);
                is_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                fill <= fill - 2'd1;
                is_full <= 1'b0;
                is_empty <= (fill == 2'd1);
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !occupied[tail]);
endmodule

// A 8-slot queue of 8-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module evt_fifo #(
    parameter WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             in_valid,
    output wire             in_ready,
    input  wire [WIDTH-1:0] in_data,
    output wire             out_valid,
    input  wire             out_ready,
    output wire [WIDTH-1:0] out_data,
    output wire [3:0]       level
);
    localparam DEPTH = 8;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [7:0] slot_full;
    reg [3:0] wr_ptr;
    reg [3:0] rd_ptr;

    initial slot_full = 8'd0;
    initial wr_ptr = 4'd0;
    initial rd_ptr = 4'd0;

    assign in_ready  = (wr_ptr != {~rd_ptr[3], rd_ptr[2:0]});
    assign out_valid = (wr_ptr != rd_ptr);
    wire do_push = in_valid && in_ready;
    wire do_pop  = out_valid && out_ready;
    assign out_data = mem[rd_ptr[2:0]];
    assign level = wr_ptr - rd_ptr;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr[2:0]] <= in_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            slot_full <= 8'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr[2:0]] <= 1'b1;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr[2:0]] <= 1'b0;
                rd_ptr <= rd_ptr + 4'd1;
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (!out_valid || slot_full[rd_ptr[2:0]]);
endmodule

