// A 2-entry lookup table of 4-bit keys and 8-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module id_table #(
    parameter KEY_W = 4,
    parameter VAL_W = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
    input  wire [VAL_W-1:0] ins_val,
    input  wire             inv_valid,
    input  wire [KEY_W-1:0] inv_key,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 2;

    reg [N-1:0] v_q;
    reg [KEY_W-1:0] key_q [0:N-1];
    reg [VAL_W-1:0] val_q [0:N-1];

    initial v_q = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] match_q;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            match_q[i0] = v_q[i0] && (key_q[i0] == lk_key);
            if (match_q[i0]) lk_val_r = val_q[i0];
        end
    end
    assign lk_hit = |match_q;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [0:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (v_q[i1] && (key_q[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg inv_hit;
    reg [0:0] inv_slot;
    integer i2;
    always @(*) begin
        inv_hit = 1'b0;
        inv_slot = 1'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (v_q[i2] && (key_q[i2] == inv_key)) begin
                inv_hit = 1'b1;
                inv_slot = i2;
            end
    end

    assign ins_ready = (ins_hit || any_free) && !inv_valid;
    wire [0:0] target = ins_hit ? ins_slot : free_slot;
    wire do_ins = ins_valid && ins_ready;
    wire do_inv = inv_valid && inv_hit;

    always @(posedge clk) begin
        if (rst) begin
            v_q <= 2'd0;
        end else if (do_inv) begin
            v_q[inv_slot] <= 1'b0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= ins_key;
            val_q[target] <= ins_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (match_q[0] + match_q[1] <= 2'd1);
endmodule

// A 4-entry lookup table of 8-bit keys and 32-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module flow_map #(
    parameter KEY_W = 8,
    parameter VAL_W = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
