    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            hit_vec[i0] = entry_valid[i0] && (tag_q[i0] == lookup_key);
            if (hit_vec[i0]) lk_val_r = data_q[i0];
        end
    end
    assign lookup_hit = |hit_vec;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [1:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (entry_valid[i1] && (tag_q[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!entry_valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg drop_hit;
    reg [1:0] drop_slot;
    integer i2;
    always @(*) begin
        drop_hit = 1'b0;
        drop_slot = 2'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (entry_valid[i2] && (tag_q[i2] == drop_key)) begin
                drop_hit = 1'b1;
                drop_slot = i2;
            end
    end

    assign fill_ready = (fill_hit || any_free) && !drop_valid;
    wire [1:0] target = fill_hit ? fill_slot : free_slot;
    wire do_ins = fill_valid && fill_ready;
    wire do_inv = drop_valid && drop_hit;

    always @(posedge clk) begin
        if (rst || flush) begin
            entry_valid <= 4'd0;
        end else if (do_inv) begin
            entry_valid[drop_slot] <= 1'b0;
        end else if (do_ins) begin
            entry_valid[target] <= 1'b1;
            tag_q[target] <= fill_key;
            data_q[target] <= fill_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (hit_vec[0] + hit_vec[1] + hit_vec[2] + hit_vec[3] <= 3'd1);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module tag_free_list (
