            fl_head <= 2'd0;
            fl_tail <= 2'd0;
            fl_count <= 3'd4;
            free_list[0] <= 2'd0;
            free_list[1] <= 2'd1;
            free_list[2] <= 2'd2;
            free_list[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                busy[free_list[fl_head]] <= 1'b1;
                fl_head <= fl_head + 2'd1;
            end
            if (do_rel) begin
                busy[rel_id] <= 1'b0;
                free_list[fl_tail] <= rel_id;
                fl_tail <= fl_tail + 2'd1;
            end
