        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            hit_vec[i0] = entry_valid[i0] && (tag_q[i0] == lookup_key);
            if (hit_vec[i0]) lk_val_r = data_q[i0];
        end
    end
    assign lookup_hit = |hit_vec;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [2:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 3'd0;
        any_free = 1'b0;
        free_slot = 3'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (entry_valid[i1] && (tag_q[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!entry_valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign fill_ready = 1'b1;
    wire [2:0] target = fill_hit ? fill_slot : (any_free ? free_slot : victim);
    wire do_ins = fill_valid && fill_ready;

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 8'd0;
            victim <= 3'd0;
        end else if (do_ins) begin
            entry_valid[target] <= 1'b1;
            tag_q[target] <= fill_key;
            data_q[target] <= fill_val;
            if (!fill_hit && !any_free) victim <= victim + 3'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (hit_vec[0] + hit_vec[1] + hit_vec[2] + hit_vec[3] + hit_vec[4] + hit_vec[5] + hit_vec[6] + hit_vec[7] <= 4'd1);
endmodule

// A 32-slot queue of 32-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module tx_queue #(
    parameter WIDTH = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             s_axis_tvalid,
    output wire             s_axis_tready,
    input  wire [WIDTH-1:0] s_axis_tdata,
    output wire             m_axis_tvalid,
    input  wire             m_axis_tready,
    output wire [WIDTH-1:0] m_axis_tdata,
    output wire [5:0]       level
);
    localparam DEPTH = 32;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [31:0] valid_q;
    reg [4:0] wptr_q;
    reg [4:0] rptr_q;
    reg [5:0] cnt_q;
    reg full_r, empty_r;

    initial valid_q = 32'd0;
    initial wptr_q = 5'd0;
    initial rptr_q = 5'd0;
    initial cnt_q = 6'd0;
    initial full_r = 1'b0;
    initial empty_r = 1'b1;

    assign s_axis_tready  = !full_r;
    assign m_axis_tvalid = !empty_r;
    wire do_push = s_axis_tvalid && s_axis_tready;
    wire do_pop  = m_axis_tvalid && m_axis_tready;
    assign m_axis_tdata = ram[rptr_q];
    assign level = cnt_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q] <= s_axis_tdata;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid_q <= 32'd0;
            wptr_q <= 5'd0;
            rptr_q <= 5'd0;
            cnt_q <= 6'd0;
            full_r <= 1'b0;
            empty_r <= 1'b1;
        end else begin
            if (do_push) begin
                valid_q[wptr_q] <= 1'b1;
                wptr_q <= wptr_q + 5'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q] <= 1'b0;
                rptr_q <= rptr_q + 5'd1;
            end
            if (do_push && !do_pop) begin
                cnt_q <= cnt_q + 6'd1;
                full_r <= (cnt_q == 6'd31);
                empty_r <= 1'b0;
            end else if (do_pop && !do_push) begin
                cnt_q <= cnt_q - 6'd1;
                full_r <= 1'b0;
                empty_r <= (cnt_q == 6'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (!m_axis_tvalid || valid_q[rptr_q]);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module credit_free_list (
    input  wire             clk,
    input  wire             rst,
    output wire             get_valid,
    input  wire             get_ready,
    output wire [1:0]       get_id,
    input  wire             put_valid,
    input  wire [1:0]       put_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] in_use;
    reg [1:0] free_ids [0:N-1];
    reg [1:0] rd_ptr;
    reg [1:0] wr_ptr;
    reg [2:0] num_free;

    initial in_use = 4'd0;
    initial rd_ptr = 2'd0;
    initial wr_ptr = 2'd0;
    initial num_free = 3'd4;
    initial free_ids[0] = 2'd0;
    initial free_ids[1] = 2'd1;
    initial free_ids[2] = 2'd2;
    initial free_ids[3] = 2'd3;

    assign get_valid = (num_free != 3'd0);
    assign get_id = free_ids[rd_ptr];
    assign free_count = num_free;
    wire do_alloc = get_valid && get_ready;
    wire do_rel = put_valid && in_use[put_id];

    always @(posedge clk) begin
        if (rst) begin
            in_use <= 4'd0;
            rd_ptr <= 2'd0;
            wr_ptr <= 2'd0;
            num_free <= 3'd4;
            free_ids[0] <= 2'd0;
            free_ids[1] <= 2'd1;
            free_ids[2] <= 2'd2;
            free_ids[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                in_use[free_ids[rd_ptr]] <= 1'b1;
                rd_ptr <= rd_ptr + 2'd1;
            end
            if (do_rel) begin
                in_use[put_id] <= 1'b0;
                free_ids[wr_ptr] <= put_id;
                wr_ptr <= wr_ptr + 2'd1;
            end
            if (do_alloc && !do_rel)
                num_free <= num_free - 3'd1;
            else if (do_rel && !do_alloc)
                num_free <= num_free + 3'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (num_free + in_use[0] + in_use[1] + in_use[2] + in_use[3] == 3'd4);
endmodule

// A 64-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module cmd_buffer #(
    parameter WIDTH = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [6:0]       level
);
    localparam DEPTH = 64;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [63:0] slot_full;
    reg [6:0] wr_ptr;
    reg [6:0] rd_ptr;

    initial slot_full = 64'd0;
    initial wr_ptr = 7'd0;
    initial rd_ptr = 7'd0;

    assign full  = (wr_ptr == {~rd_ptr[6], rd_ptr[5:0]});
    assign empty = (wr_ptr == rd_ptr);
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = mem[rd_ptr[5:0]];
    assign level = wr_ptr - rd_ptr;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr[5:0]] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            slot_full <= 64'd0;
            wr_ptr <= 7'd0;
            rd_ptr <= 7'd0;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr[5:0]] <= 1'b1;
                wr_ptr <= wr_ptr + 7'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr[5:0]] <= 1'b0;
                rd_ptr <= rd_ptr + 7'd1;
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !slot_full[wr_ptr[5:0]]);
endmodule

// A 2-slot queue of 64-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module evt_queue #(
    parameter WIDTH = 64
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             enq_valid,
    output wire             enq_ready,
    input  wire [WIDTH-1:0] enq_data,
    output wire             deq_valid,
    input  wire             deq_ready,
    output wire [WIDTH-1:0] deq_data,
    output wire [1:0]       occupancy
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] entries [0:DEPTH-1];
    reg [1:0] entry_valid;
    reg [0:0] waddr;
    reg [0:0] raddr;
    reg [1:0] used;
    reg r_full, r_empty;

    initial entry_valid = 2'd0;
    initial waddr = 1'd0;
    initial raddr = 1'd0;
    initial used = 2'd0;
    initial r_full = 1'b0;
    initial r_empty = 1'b1;

    assign enq_ready  = !r_full;
    assign deq_valid = !r_empty;
    wire do_push = enq_valid && enq_ready;
    wire do_pop  = deq_valid && deq_ready;
    assign deq_data = entries[raddr];
    assign occupancy = used;

    always @(posedge clk) begin
        if (do_push) entries[waddr] <= enq_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 2'd0;
            waddr <= 1'd0;
            raddr <= 1'd0;
            used <= 2'd0;
            r_full <= 1'b0;
            r_empty <= 1'b1;
        end else begin
            if (do_push) begin
                entry_valid[waddr] <= 1'b1;
                waddr <= waddr + 1'd1;
            end
            if (do_pop) begin
                entry_valid[raddr] <= 1'b0;
                raddr <= raddr + 1'd1;
            end
            if (do_push && !do_pop) begin
                used <= used + 2'd1;
                r_full <= (used == 2'd1);
                r_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                used <= used - 2'd1;
                r_full <= 1'b0;
                r_empty <= (used == 2'd1);
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (!enq_ready || !entry_valid[waddr]);
endmodule

// A pool of 8 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module phys_reg_free_list (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    output wire             get_valid,
    input  wire             get_ready,
    output wire [2:0]       get_id,
    input  wire             put_valid,
