    reg [2:0] wr_ptr;
    reg [3:0] num_free;

    initial in_use = 8'd0;
    initial rd_ptr = 3'd0;
    initial wr_ptr = 3'd0;
    initial num_free = 4'd8;
    initial free_ids[0] = 3'd0;
    initial free_ids[1] = 3'd1;
    initial free_ids[2] = 3'd2;
    initial free_ids[3] = 3'd3;
    initial free_ids[4] = 3'd4;
    initial free_ids[5] = 3'd5;
    initial free_ids[6] = 3'd6;
    initial free_ids[7] = 3'd7;

    assign get_valid = (num_free != 4'd0);
    assign get_id = free_ids[rd_ptr];
    assign free_count = num_free;
    wire do_alloc = get_valid && get_ready;
    wire do_rel = put_valid && in_use[put_id];

    always @(posedge clk) begin
        if (rst || flush) begin
            in_use <= 8'd0;
            rd_ptr <= 3'd0;
            wr_ptr <= 3'd0;
            num_free <= 4'd8;
            free_ids[0] <= 3'd0;
            free_ids[1] <= 3'd1;
            free_ids[2] <= 3'd2;
            free_ids[3] <= 3'd3;
