    reg [3:0] head;

    initial occupied = 8'd0;
    initial tail = 4'd0;
    initial head = 4'd0;

    assign s_axis_tready  = (tail != {~head[3], head[2:0]});
    assign m_axis_tvalid = (tail != head);
    wire do_push = s_axis_tvalid && s_axis_tready;
    wire do_pop  = m_axis_tvalid && m_axis_tready;
    assign m_axis_tdata = storage[head[2:0]];
    assign fill_level = tail - head;

    always @(posedge clk) begin
        if (do_push) storage[tail[2:0]] <= s_axis_tdata;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            occupied <= 8'd0;
            tail <= 4'd0;
            head <= 4'd0;
        end else begin
            if (do_push) begin
                occupied[tail[2:0]] <= 1'b1;
                tail <= tail + 4'd1;
            end
            if (do_pop) begin
                occupied[head[2:0]] <= 1'b0;
                head <= head + 4'd1;
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (!m_axis_tvalid || occupied[head[2:0]]);
endmodule

