    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [3:0]       level
);
    localparam DEPTH = 8;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [7:0] slot_full;
    reg [2:0] wr_ptr;
    reg [2:0] rd_ptr;
    reg [3:0] count;
    reg full_q, empty_q;

