    wire do_pop  = deq_valid && deq_ready;
    assign deq_data = entries[raddr];
    assign occupancy = used;

    always @(posedge clk) begin
        if (do_push) entries[waddr] <= enq_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 16'd0;
            waddr <= 4'd0;
            raddr <= 4'd0;
            used <= 5'd0;
        end else begin
            if (do_push) begin
                entry_valid[waddr] <= 1'b1;
                waddr <= waddr + 4'd1;
