        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (!deq_valid || entry_valid[raddr]);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module credit_free_list (
    input  wire             clk,
    input  wire             rst,
    output wire             take_valid,
    input  wire             take_ready,
    output wire [1:0]       take_id,
    input  wire             give_valid,
    input  wire [1:0]       give_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] busy;
    reg [1:0] free_list [0:N-1];
    reg [1:0] fl_head;
    reg [1:0] fl_tail;
    reg [2:0] fl_count;

    initial busy = 4'd0;
    initial fl_head = 2'd0;
    initial fl_tail = 2'd0;
    initial fl_count = 3'd4;
    initial free_list[0] = 2'd0;
    initial free_list[1] = 2'd1;
    initial free_list[2] = 2'd2;
    initial free_list[3] = 2'd3;

    assign take_valid = (fl_count != 3'd0);
    assign take_id = free_list[fl_head];
    assign free_count = fl_count;
    wire do_alloc = take_valid && take_ready;
    wire do_rel = give_valid && busy[give_id];

    always @(posedge clk) begin
        if (rst) begin
            busy <= 4'd0;
            fl_head <= 2'd0;
            fl_tail <= 2'd0;
            fl_count <= 3'd4;
            free_list[0] <= 2'd0;
            free_list[1] <= 2'd1;
            free_list[2] <= 2'd2;
            free_list[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                busy[free_list[fl_head]] <= 1'b1;
                fl_head <= fl_head + 2'd1;
            end
            if (do_rel) begin
                busy[give_id] <= 1'b0;
                free_list[fl_tail] <= give_id;
                fl_tail <= fl_tail + 2'd1;
            end
            if (do_alloc && !do_rel)
                fl_count <= fl_count - 3'd1;
            else if (do_rel && !do_alloc)
                fl_count <= fl_count + 3'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (fl_count + busy[0] + busy[1] + busy[2] + busy[3] == 3'd4);
