// A 2-slot queue of 64-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module job_fifo #(
    parameter WIDTH = 64
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             s_axis_tvalid,
    output wire             s_axis_tready,
    input  wire [WIDTH-1:0] s_axis_tdata,
    output wire             m_axis_tvalid,
    input  wire             m_axis_tready,
    output wire [WIDTH-1:0] m_axis_tdata,
    output wire [1:0]       fill_level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [1:0] occupied;
    reg [0:0] tail;
    reg [0:0] head;
    reg [1:0] fill;
    reg is_full, is_empty;

    initial occupied = 2'd0;
    initial tail = 1'd0;
    initial head = 1'd0;
    initial fill = 2'd0;
    initial is_full = 1'b0;
    initial is_empty = 1'b1;

    assign s_axis_tready  = !is_full;
    assign m_axis_tvalid = !is_empty;
    wire do_push = s_axis_tvalid && s_axis_tready;
    wire do_pop  = m_axis_tvalid && m_axis_tready;
    assign m_axis_tdata = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= s_axis_tdata;
    end

    always @(posedge clk) begin
        if (rst) begin
            occupied <= 2'd0;
            tail <= 1'd0;
            head <= 1'd0;
            fill <= 2'd0;
            is_full <= 1'b0;
            is_empty <= 1'b1;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 1'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 1'd1;
            end
            if (do_push && !do_pop) begin
                fill <= fill + 2'd1;
                is_full <= (fill == 2'd1);
                is_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                fill <= fill - 2'd1;
                is_full <= 1'b0;
                is_empty <= (fill == 2'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (!m_axis_tvalid || occupied[head]);
endmodule

