// A 4-entry lookup table of 32-bit keys and 4-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free the sender waits.
module flow_map #(
    parameter KEY_W = 32,
    parameter VAL_W = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
    input  wire             drop_valid,
    input  wire [KEY_W-1:0] drop_key,
    input  wire [KEY_W-1:0] lookup_key,
    output wire             lookup_hit,
    output wire [VAL_W-1:0] lookup_val
);
    localparam N = 4;

    reg [N-1:0] v_q;
    reg [KEY_W-1:0] key_q [0:N-1];
    reg [VAL_W-1:0] val_q [0:N-1];

    initial v_q = 4'd0;

    // lookup: every entry compared at once
    reg [N-1:0] match_q;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            match_q[i0] = v_q[i0] && (key_q[i0] == lookup_key);
            if (match_q[i0]) lk_val_r = val_q[i0];
        end
    end
    assign lookup_hit = |match_q;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [1:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (v_q[i1] && (key_q[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg drop_hit;
    reg [1:0] drop_slot;
    integer i2;
    always @(*) begin
        drop_hit = 1'b0;
        drop_slot = 2'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (v_q[i2] && (key_q[i2] == drop_key)) begin
                drop_hit = 1'b1;
                drop_slot = i2;
            end
    end

    assign fill_ready = (fill_hit || any_free) && !drop_valid;
    wire [1:0] target = fill_hit ? fill_slot : free_slot;
    wire do_ins = fill_valid && fill_ready;
    wire do_inv = drop_valid && drop_hit;

    always @(posedge clk) begin
        if (rst || flush) begin
            v_q <= 4'd0;
        end else if (do_inv) begin
            v_q[drop_slot] <= 1'b0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= fill_key;
            val_q[target] <= fill_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (match_q[0] + match_q[1] + match_q[2] + match_q[3] <= 3'd1);
endmodule

// A 8-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module pkt_queue #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [3:0]       level
);
    localparam DEPTH = 8;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [7:0] slot_full;
    reg [2:0] wr_ptr;
    reg [2:0] rd_ptr;
    reg [3:0] count;
    reg full_q, empty_q;

    initial slot_full = 8'd0;
    initial wr_ptr = 3'd0;
    initial rd_ptr = 3'd0;
    initial count = 4'd0;
    initial full_q = 1'b0;
    initial empty_q = 1'b1;

    assign full  = full_q;
    assign empty = empty_q;
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = mem[rd_ptr];
    assign level = count;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            slot_full <= 8'd0;
            wr_ptr <= 3'd0;
            rd_ptr <= 3'd0;
            count <= 4'd0;
            full_q <= 1'b0;
            empty_q <= 1'b1;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr] <= 1'b1;
                wr_ptr <= wr_ptr + 3'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr] <= 1'b0;
                rd_ptr <= rd_ptr + 3'd1;
            end
            if (do_push && !do_pop) begin
                count <= count + 4'd1;
                full_q <= (count == 4'd7);
                empty_q <= 1'b0;
            end else if (do_pop && !do_push) begin
                count <= count - 4'd1;
                full_q <= 1'b0;
                empty_q <= (count == 4'd1);
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (full || !slot_full[wr_ptr]);
endmodule

// A pool of 8 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module phys_reg_allocator (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    output wire             take_valid,
    input  wire             take_ready,
    output wire [2:0]       take_id,
    input  wire             give_valid,
    input  wire [2:0]       give_id,
    output wire [3:0]       free_count
);
    localparam N = 8;

    reg [N-1:0] in_use;
    reg [2:0] free_ids [0:N-1];
    reg [2:0] rd_ptr;
    reg [2:0] wr_ptr;
    reg [3:0] num_free;

    initial in_use = 8'd0;
    initial rd_ptr = 3'd0;
    initial wr_ptr = 3'd0;
    initial num_free = 4'd8;
    initial free_ids[0] = 3'd0;
    initial free_ids[1] = 3'd1;
    initial free_ids[2] = 3'd2;
    initial free_ids[3] = 3'd3;
    initial free_ids[4] = 3'd4;
    initial free_ids[5] = 3'd5;
    initial free_ids[6] = 3'd6;
    initial free_ids[7] = 3'd7;

    assign take_valid = (num_free != 4'd0);
    assign take_id = free_ids[rd_ptr];
    assign free_count = num_free;
    wire do_alloc = take_valid && take_ready;
    wire do_rel = give_valid && in_use[give_id];

    always @(posedge clk) begin
        if (rst || flush) begin
            in_use <= 8'd0;
            rd_ptr <= 3'd0;
            wr_ptr <= 3'd0;
            num_free <= 4'd8;
            free_ids[0] <= 3'd0;
            free_ids[1] <= 3'd1;
            free_ids[2] <= 3'd2;
            free_ids[3] <= 3'd3;
            free_ids[4] <= 3'd4;
            free_ids[5] <= 3'd5;
            free_ids[6] <= 3'd6;
            free_ids[7] <= 3'd7;
        end else begin
            if (do_alloc) begin
                in_use[free_ids[rd_ptr]] <= 1'b1;
                rd_ptr <= rd_ptr + 3'd1;
            end
            if (do_rel) begin
                in_use[give_id] <= 1'b0;
                free_ids[wr_ptr] <= give_id;
                wr_ptr <= wr_ptr + 3'd1;
            end
            if (do_alloc && !do_rel)
                num_free <= num_free - 4'd1;
            else if (do_rel && !do_alloc)
                num_free <= num_free + 4'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (num_free + in_use[0] + in_use[1] + in_use[2] + in_use[3] + in_use[4] + in_use[5] + in_use[6] + in_use[7] == 4'd8);
endmodule

