    input  wire             inv_valid,
    input  wire [KEY_W-1:0] inv_key,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 2;

    reg [N-1:0] entry_valid;
    reg [KEY_W-1:0] tag_q [0:N-1];
    reg [VAL_W-1:0] data_q [0:N-1];

    initial entry_valid = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] hit_vec;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            hit_vec[i0] = entry_valid[i0] && (tag_q[i0] == lk_key);
            if (hit_vec[i0]) lk_val_r = data_q[i0];
        end
    end
    assign lk_hit = |hit_vec;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [0:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (entry_valid[i1] && (tag_q[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!entry_valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg inv_hit;
    reg [0:0] inv_slot;
    integer i2;
    always @(*) begin
        inv_hit = 1'b0;
        inv_slot = 1'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (entry_valid[i2] && (tag_q[i2] == inv_key)) begin
                inv_hit = 1'b1;
                inv_slot = i2;
            end
    end

    assign ins_ready = (ins_hit || any_free) && !inv_valid;
    wire [0:0] target = ins_hit ? ins_slot : free_slot;
    wire do_ins = ins_valid && ins_ready;
    wire do_inv = inv_valid && inv_hit;

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 2'd0;
        end else if (do_inv) begin
            entry_valid[inv_slot] <= 1'b0;
        end else if (do_ins) begin
            entry_valid[target] <= 1'b1;
            tag_q[target] <= ins_key;
            data_q[target] <= ins_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (hit_vec[0] + hit_vec[1] <= 2'd1);
endmodule

// A 4-slot queue of 4-bit items with a full bit per slot; the sender waits when it is full. Full and empty come from an extra pointer bit.
module tx_queue #(
    parameter WIDTH = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             in_valid,
    output wire             in_ready,
    input  wire [WIDTH-1:0] in_data,
    output wire             out_valid,
    input  wire             out_ready,
    output wire [WIDTH-1:0] out_data,
    output wire [2:0]       occupancy
);
    localparam DEPTH = 4;

    reg [WIDTH-1:0] entries [0:DEPTH-1];
    reg [3:0] entry_valid;
    reg [2:0] waddr;
    reg [2:0] raddr;

    initial entry_valid = 4'd0;
    initial waddr = 3'd0;
    initial raddr = 3'd0;

    assign in_ready  = (waddr != {~raddr[2], raddr[1:0]});
    assign out_valid = (waddr != raddr);
    wire do_push = in_valid && in_ready;
    wire do_pop  = out_valid && out_ready;
    assign out_data = entries[raddr[1:0]];
    assign occupancy = waddr - raddr;

    always @(posedge clk) begin
        if (do_push) entries[waddr[1:0]] <= in_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 4'd0;
            waddr <= 3'd0;
            raddr <= 3'd0;
        end else begin
            if (do_push) begin
                entry_valid[waddr[1:0]] <= 1'b1;
                waddr <= waddr + 3'd1;
            end
            if (do_pop) begin
                entry_valid[raddr[1:0]] <= 1'b0;
                raddr <= raddr + 3'd1;
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (!out_valid || entry_valid[raddr[1:0]]);
endmodule

// A 2-slot queue of 8-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module rx_fifo #(
    parameter WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             s_axis_tvalid,
    output wire             s_axis_tready,
    input  wire [WIDTH-1:0] s_axis_tdata,
    output wire             m_axis_tvalid,
    input  wire             m_axis_tready,
    output wire [WIDTH-1:0] m_axis_tdata,
    output wire [1:0]       fill_level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [1:0] occupied;
    reg [0:0] tail;
    reg [0:0] head;
    reg [1:0] fill;
    reg is_full, is_empty;

    initial occupied = 2'd0;
    initial tail = 1'd0;
    initial head = 1'd0;
    initial fill = 2'd0;
    initial is_full = 1'b0;
    initial is_empty = 1'b1;

    assign s_axis_tready  = !is_full;
    assign m_axis_tvalid = !is_empty;
    wire do_push = s_axis_tvalid && s_axis_tready;
    wire do_pop  = m_axis_tvalid && m_axis_tready;
    assign m_axis_tdata = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= s_axis_tdata;
    end

    always @(posedge clk) begin
        if (rst) begin
            occupied <= 2'd0;
            tail <= 1'd0;
            head <= 1'd0;
            fill <= 2'd0;
            is_full <= 1'b0;
            is_empty <= 1'b1;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 1'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 1'd1;
            end
            if (do_push && !do_pop) begin
                fill <= fill + 2'd1;
                is_full <= (fill == 2'd1);
                is_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                fill <= fill - 2'd1;
                is_full <= 1'b0;
                is_empty <= (fill == 2'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (!m_axis_tvalid || occupied[head]);
endmodule

// A 2-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module tag_queue #(
    parameter WIDTH = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             push,
    output wire             full,
    input  wire [WIDTH-1:0] push_data,
    input  wire             pop,
    output wire             empty,
    output wire [WIDTH-1:0] pop_data,
    output wire [1:0]       fill_level
);
    localparam DEPTH = 2;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [1:0] occupied;
    reg [0:0] tail;
    reg [0:0] head;
    reg [1:0] fill;
    reg is_full, is_empty;

    initial occupied = 2'd0;
    initial tail = 1'd0;
    initial head = 1'd0;
    initial fill = 2'd0;
    initial is_full = 1'b0;
    initial is_empty = 1'b1;

    assign full  = is_full;
    assign empty = is_empty;
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;
    assign pop_data = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= push_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            occupied <= 2'd0;
            tail <= 1'd0;
            head <= 1'd0;
            fill <= 2'd0;
            is_full <= 1'b0;
            is_empty <= 1'b1;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 1'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 1'd1;
            end
            if (do_push && !do_pop) begin
                fill <= fill + 2'd1;
                is_full <= (fill == 2'd1);
                is_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                fill <= fill - 2'd1;
                is_full <= 1'b0;
                is_empty <= (fill == 2'd1);
            end
        end
    end

    // what is read always comes from a filled slot
    always @(posedge clk) assert (empty || occupied[head]);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module slot_free_list (
    input  wire             clk,
    input  wire             rst,
    output wire             take_valid,
    input  wire             take_ready,
    output wire [1:0]       take_id,
    input  wire             give_valid,
    input  wire [1:0]       give_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] out_q;
    reg [1:0] spare [0:N-1];
    reg [1:0] get_ptr;
    reg [1:0] put_ptr;
    reg [2:0] n_free;

    initial out_q = 4'd0;
    initial get_ptr = 2'd0;
    initial put_ptr = 2'd0;
    initial n_free = 3'd4;
    initial spare[0] = 2'd0;
    initial spare[1] = 2'd1;
    initial spare[2] = 2'd2;
    initial spare[3] = 2'd3;

    assign take_valid = (n_free != 3'd0);
    assign take_id = spare[get_ptr];
    assign free_count = n_free;
    wire do_alloc = take_valid && take_ready;
    wire do_rel = give_valid && out_q[give_id];

    always @(posedge clk) begin
        if (rst) begin
            out_q <= 4'd0;
            get_ptr <= 2'd0;
            put_ptr <= 2'd0;
            n_free <= 3'd4;
            spare[0] <= 2'd0;
            spare[1] <= 2'd1;
            spare[2] <= 2'd2;
            spare[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                out_q[spare[get_ptr]] <= 1'b1;
                get_ptr <= get_ptr + 2'd1;
            end
            if (do_rel) begin
                out_q[give_id] <= 1'b0;
                spare[put_ptr] <= give_id;
                put_ptr <= put_ptr + 2'd1;
            end
            if (do_alloc && !do_rel)
                n_free <= n_free - 3'd1;
            else if (do_rel && !do_alloc)
                n_free <= n_free + 3'd1;
        end
    end

    // an ID on offer is never in use
    always @(posedge clk) assert (!take_valid || !out_q[take_id]);
endmodule

// A 16-slot queue of 16-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module msg_queue #(
    parameter WIDTH = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             in_valid,
    output wire             in_ready,
    input  wire [WIDTH-1:0] in_data,
    output wire             out_valid,
    input  wire             out_ready,
    output wire [WIDTH-1:0] out_data,
    output wire [4:0]       level
);
    localparam DEPTH = 16;

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [15:0] valid_q;
    reg [3:0] wptr_q;
    reg [3:0] rptr_q;
    reg [4:0] cnt_q;
    reg full_r, empty_r;

    initial valid_q = 16'd0;
    initial wptr_q = 4'd0;
    initial rptr_q = 4'd0;
    initial cnt_q = 5'd0;
    initial full_r = 1'b0;
    initial empty_r = 1'b1;

    assign in_ready  = !full_r;
    assign out_valid = !empty_r;
    wire do_push = in_valid && in_ready;
    wire do_pop  = out_valid && out_ready;
    assign out_data = ram[rptr_q];
    assign level = cnt_q;

    always @(posedge clk) begin
        if (do_push) ram[wptr_q] <= in_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            valid_q <= 16'd0;
            wptr_q <= 4'd0;
            rptr_q <= 4'd0;
            cnt_q <= 5'd0;
            full_r <= 1'b0;
            empty_r <= 1'b1;
        end else begin
            if (do_push) begin
                valid_q[wptr_q] <= 1'b1;
                wptr_q <= wptr_q + 4'd1;
            end
            if (do_pop) begin
                valid_q[rptr_q] <= 1'b0;
                rptr_q <= rptr_q + 4'd1;
            end
            if (do_push && !do_pop) begin
                cnt_q <= cnt_q + 5'd1;
                full_r <= (cnt_q == 5'd15);
                empty_r <= 1'b0;
            end else if (do_pop && !do_push) begin
                cnt_q <= cnt_q - 5'd1;
                full_r <= 1'b0;
                empty_r <= (cnt_q == 5'd1);
            end
        end
    end

    // a write never lands on a filled slot
    always @(posedge clk) assert (!in_ready || !valid_q[wptr_q]);
endmodule

// A 2-entry lookup table of 12-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
