    reg [N-1:0] entry_valid;
    reg [KEY_W-1:0] tag_q [0:N-1];
    reg [VAL_W-1:0] data_q [0:N-1];
    reg [0:0] victim;

    initial entry_valid = 2'd0;
    initial victim = 1'd0;

    // lookup: every entry compared at once
    reg [N-1:0] hit_vec;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            hit_vec[i0] = entry_valid[i0] && (tag_q[i0] == lk_key);
            if (hit_vec[i0]) lk_val_r = data_q[i0];
        end
    end
    assign lk_hit = |hit_vec;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [0:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (entry_valid[i1] && (tag_q[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!entry_valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign ins_ready = 1'b1;
    wire [0:0] target = ins_hit ? ins_slot : (any_free ? free_slot : victim);
    wire do_ins = ins_valid && ins_ready;

    always @(posedge clk) begin
        if (rst) begin
            entry_valid <= 2'd0;
            victim <= 1'd0;
        end else if (do_ins) begin
            entry_valid[target] <= 1'b1;
            tag_q[target] <= ins_key;
            data_q[target] <= ins_val;
            if (!ins_hit && !any_free) victim <= victim + 1'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (hit_vec[0] + hit_vec[1] <= 2'd1);
endmodule

// A 32-slot queue of 1-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module pkt_fifo #(
    parameter WIDTH = 1
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [5:0]       level
);
    localparam DEPTH = 32;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [31:0] slot_full;
    reg [4:0] wr_ptr;
    reg [4:0] rd_ptr;
    reg [5:0] count;
    reg full_q, empty_q;

    initial slot_full = 32'd0;
    initial wr_ptr = 5'd0;
    initial rd_ptr = 5'd0;
    initial count = 6'd0;
    initial full_q = 1'b0;
    initial empty_q = 1'b1;

    assign full  = full_q;
    assign empty = empty_q;
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = mem[rd_ptr];
    assign level = count;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            slot_full <= 32'd0;
            wr_ptr <= 5'd0;
            rd_ptr <= 5'd0;
            count <= 6'd0;
            full_q <= 1'b0;
            empty_q <= 1'b1;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr] <= 1'b1;
                wr_ptr <= wr_ptr + 5'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr] <= 1'b0;
                rd_ptr <= rd_ptr + 5'd1;
            end
            if (do_push && !do_pop) begin
                count <= count + 6'd1;
                full_q <= (count == 6'd31);
                empty_q <= 1'b0;
            end else if (do_pop && !do_push) begin
                count <= count - 6'd1;
                full_q <= 1'b0;
                empty_q <= (count == 6'd1);
            end
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert (count == slot_full[0] + slot_full[1] + slot_full[2] + slot_full[3] + slot_full[4] + slot_full[5] + slot_full[6] + slot_full[7] + slot_full[8] + slot_full[9] + slot_full[10] + slot_full[11] + slot_full[12] + slot_full[13] + slot_full[14] + slot_full[15] + slot_full[16] + slot_full[17] + slot_full[18] + slot_full[19] + slot_full[20] + slot_full[21] + slot_full[22] + slot_full[23] + slot_full[24] + slot_full[25] + slot_full[26] + slot_full[27] + slot_full[28] + slot_full[29] + slot_full[30] + slot_full[31]);
endmodule

// A 2-entry lookup table of 12-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module id_table #(
    parameter KEY_W = 12,
    parameter VAL_W = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
    input  wire [KEY_W-1:0] lookup_key,
    output wire             lookup_hit,
    output wire [VAL_W-1:0] lookup_val
);
