    reg [0:0] victim;

    initial v_q = 2'd0;
    initial victim = 1'd0;

    // lookup: every entry compared at once
    reg [N-1:0] match_q;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            match_q[i0] = v_q[i0] && (key_q[i0] == lookup_key);
            if (match_q[i0]) lk_val_r = val_q[i0];
        end
    end
    assign lookup_hit = |match_q;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [0:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (v_q[i1] && (key_q[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign fill_ready = 1'b1;
    wire [0:0] target = fill_hit ? fill_slot : (any_free ? free_slot : victim);
    wire do_ins = fill_valid && fill_ready;

    always @(posedge clk) begin
        if (rst || flush) begin
            v_q <= 2'd0;
            victim <= 1'd0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= fill_key;
            val_q[target] <= fill_val;
            if (!fill_hit && !any_free) victim <= victim + 1'd1;
