        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            match_q[i0] = v_q[i0] && (key_q[i0] == lk_key);
            if (match_q[i0]) lk_val_r = val_q[i0];
        end
    end
    assign lk_hit = |match_q;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [0:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 1'd0;
        any_free = 1'b0;
        free_slot = 1'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (v_q[i1] && (key_q[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!v_q[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg inv_hit;
    reg [0:0] inv_slot;
    integer i2;
    always @(*) begin
        inv_hit = 1'b0;
        inv_slot = 1'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (v_q[i2] && (key_q[i2] == inv_key)) begin
                inv_hit = 1'b1;
                inv_slot = i2;
            end
    end

    assign ins_ready = (ins_hit || any_free) && !inv_valid;
    wire [0:0] target = ins_hit ? ins_slot : free_slot;
    wire do_ins = ins_valid && ins_ready;
    wire do_inv = inv_valid && inv_hit;

    always @(posedge clk) begin
        if (rst) begin
            v_q <= 2'd0;
        end else if (do_inv) begin
            v_q[inv_slot] <= 1'b0;
        end else if (do_ins) begin
            v_q[target] <= 1'b1;
            key_q[target] <= ins_key;
            val_q[target] <= ins_val;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (match_q[0] + match_q[1] <= 2'd1);
endmodule

// A pool of 4 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module phys_reg_free_list (
    input  wire             clk,
    input  wire             rst,
    output wire             get_valid,
    input  wire             get_ready,
    output wire [1:0]       get_id,
    input  wire             put_valid,
    input  wire [1:0]       put_id,
    output wire [2:0]       free_count
);
    localparam N = 4;

    reg [N-1:0] in_use;
    reg [1:0] free_ids [0:N-1];
    reg [1:0] rd_ptr;
    reg [1:0] wr_ptr;
    reg [2:0] num_free;

    initial in_use = 4'd0;
    initial rd_ptr = 2'd0;
    initial wr_ptr = 2'd0;
    initial num_free = 3'd4;
    initial free_ids[0] = 2'd0;
    initial free_ids[1] = 2'd1;
    initial free_ids[2] = 2'd2;
    initial free_ids[3] = 2'd3;

    assign get_valid = (num_free != 3'd0);
    assign get_id = free_ids[rd_ptr];
    assign free_count = num_free;
    wire do_alloc = get_valid && get_ready;
    wire do_rel = put_valid && in_use[put_id];

    always @(posedge clk) begin
        if (rst) begin
            in_use <= 4'd0;
            rd_ptr <= 2'd0;
            wr_ptr <= 2'd0;
            num_free <= 3'd4;
            free_ids[0] <= 2'd0;
            free_ids[1] <= 2'd1;
            free_ids[2] <= 2'd2;
            free_ids[3] <= 2'd3;
        end else begin
            if (do_alloc) begin
                in_use[free_ids[rd_ptr]] <= 1'b1;
                rd_ptr <= rd_ptr + 2'd1;
            end
            if (do_rel) begin
                in_use[put_id] <= 1'b0;
                free_ids[wr_ptr] <= put_id;
                wr_ptr <= wr_ptr + 2'd1;
            end
            if (do_alloc && !do_rel)
                num_free <= num_free - 3'd1;
            else if (do_rel && !do_alloc)
                num_free <= num_free + 3'd1;
        end
    end

    // an ID on offer is never in use
    always @(posedge clk) assert (!get_valid || !in_use[get_id]);
endmodule

