// A 8-slot queue of 32-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module tx_queue #(
    parameter WIDTH = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             s_axis_tvalid,
    output wire             s_axis_tready,
    input  wire [WIDTH-1:0] s_axis_tdata,
    output wire             m_axis_tvalid,
    input  wire             m_axis_tready,
    output wire [WIDTH-1:0] m_axis_tdata,
    output wire [3:0]       fill_level
);
    localparam DEPTH = 8;

    reg [WIDTH-1:0] storage [0:DEPTH-1];
    reg [7:0] occupied;
    reg [2:0] tail;
    reg [2:0] head;
    reg [3:0] fill;
    reg is_full, is_empty;

    initial occupied = 8'd0;
    initial tail = 3'd0;
    initial head = 3'd0;
    initial fill = 4'd0;
    initial is_full = 1'b0;
    initial is_empty = 1'b1;

    assign s_axis_tready  = !is_full;
    assign m_axis_tvalid = !is_empty;
    wire do_push = s_axis_tvalid && s_axis_tready;
    wire do_pop  = m_axis_tvalid && m_axis_tready;
    assign m_axis_tdata = storage[head];
    assign fill_level = fill;

    always @(posedge clk) begin
        if (do_push) storage[tail] <= s_axis_tdata;
    end

    always @(posedge clk) begin
        if (rst) begin
            occupied <= 8'd0;
            tail <= 3'd0;
            head <= 3'd0;
            fill <= 4'd0;
            is_full <= 1'b0;
            is_empty <= 1'b1;
        end else begin
            if (do_push) begin
                occupied[tail] <= 1'b1;
                tail <= tail + 3'd1;
            end
            if (do_pop) begin
                occupied[head] <= 1'b0;
                head <= head + 3'd1;
            end
            if (do_push && !do_pop) begin
                fill <= fill + 4'd1;
                is_full <= (fill == 4'd7);
                is_empty <= 1'b0;
            end else if (do_pop && !do_push) begin
                fill <= fill - 4'd1;
                is_full <= 1'b0;
                is_empty <= (fill == 4'd1);
            end
        end
    end

    // the count equals the number of filled slots
    always @(posedge clk) assert (fill == occupied[0] + occupied[1] + occupied[2] + occupied[3] + occupied[4] + occupied[5] + occupied[6] + occupied[7]);
endmodule

// A 4-entry lookup table of 16-bit keys and 16-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module flow_map #(
    parameter KEY_W = 16,
    parameter VAL_W = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             ins_valid,
    output wire             ins_ready,
    input  wire [KEY_W-1:0] ins_key,
    input  wire [VAL_W-1:0] ins_val,
    input  wire [KEY_W-1:0] lk_key,
    output wire             lk_hit,
    output wire [VAL_W-1:0] lk_val
);
    localparam N = 4;

    reg [N-1:0] valid;
    reg [KEY_W-1:0] keys [0:N-1];
    reg [VAL_W-1:0] vals [0:N-1];
    reg [1:0] victim;

    initial valid = 4'd0;
    initial victim = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] lk_match;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            lk_match[i0] = valid[i0] && (keys[i0] == lk_key);
            if (lk_match[i0]) lk_val_r = vals[i0];
        end
    end
    assign lk_hit = |lk_match;
    assign lk_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg ins_hit, any_free;
    reg [1:0] ins_slot, free_slot;
    integer i1;
    always @(*) begin
        ins_hit = 1'b0;
        ins_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (valid[i1] && (keys[i1] == ins_key)) begin
                ins_hit = 1'b1;
                ins_slot = i1;
            end
            if (!valid[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    assign ins_ready = 1'b1;
    wire [1:0] target = ins_hit ? ins_slot : (any_free ? free_slot : victim);
    wire do_ins = ins_valid && ins_ready;

    always @(posedge clk) begin
        if (rst || flush) begin
            valid <= 4'd0;
            victim <= 2'd0;
        end else if (do_ins) begin
            valid[target] <= 1'b1;
            keys[target] <= ins_key;
            vals[target] <= ins_val;
            if (!ins_hit && !any_free) victim <= victim + 2'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (lk_match[0] + lk_match[1] + lk_match[2] + lk_match[3] <= 3'd1);
endmodule

