// A 16-slot queue of 32-bit items with a full bit per slot; the sender waits when it is full. Full and empty are kept in registers.
module evt_queue #(
    parameter WIDTH = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             flush,
    input  wire             wr_en,
    output wire             full,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output wire             empty,
    output wire [WIDTH-1:0] rd_data,
    output wire [4:0]       level
);
    localparam DEPTH = 16;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [15:0] slot_full;
    reg [3:0] wr_ptr;
    reg [3:0] rd_ptr;
    reg [4:0] count;
    reg full_q, empty_q;

    initial slot_full = 16'd0;
    initial wr_ptr = 4'd0;
    initial rd_ptr = 4'd0;
    initial count = 5'd0;
    initial full_q = 1'b0;
    initial empty_q = 1'b1;

    assign full  = full_q;
    assign empty = empty_q;
    wire do_push = wr_en && !full;
    wire do_pop  = rd_en && !empty;
    assign rd_data = mem[rd_ptr];
    assign level = count;

    always @(posedge clk) begin
        if (do_push) mem[wr_ptr] <= wr_data;
    end

    always @(posedge clk) begin
        if (rst || flush) begin
            slot_full <= 16'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
            count <= 5'd0;
            full_q <= 1'b0;
            empty_q <= 1'b1;
        end else begin
            if (do_push) begin
                slot_full[wr_ptr] <= 1'b1;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (do_pop) begin
                slot_full[rd_ptr] <= 1'b0;
                rd_ptr <= rd_ptr + 4'd1;
            end
            if (do_push && !do_pop) begin
                count <= count + 5'd1;
                full_q <= (count == 5'd15);
                empty_q <= 1'b0;
            end else if (do_pop && !do_push) begin
                count <= count - 5'd1;
                full_q <= 1'b0;
                empty_q <= (count == 5'd1);
