// A 2-entry lookup table of 32-bit keys and 32-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module session_map #(
    parameter KEY_W = 32,
    parameter VAL_W = 32
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             fill_valid,
