// A pool of 8 IDs: free IDs wait in a ring list; an allocation hands out the first one and marks it in use, and an ID in use goes back on the list when it is released, so no ID is ever out twice.
module slot_free_list (
    input  wire             clk,
    input  wire             rst,
    output wire             take_valid,
    input  wire             take_ready,
    output wire [2:0]       take_id,
    input  wire             give_valid,
    input  wire [2:0]       give_id,
    output wire [3:0]       free_count
);
    localparam N = 8;

    reg [N-1:0] out_q;
    reg [2:0] spare [0:N-1];
    reg [2:0] get_ptr;
    reg [2:0] put_ptr;
    reg [3:0] n_free;

    initial out_q = 8'd0;
    initial get_ptr = 3'd0;
    initial put_ptr = 3'd0;
    initial n_free = 4'd8;
    initial spare[0] = 3'd0;
    initial spare[1] = 3'd1;
    initial spare[2] = 3'd2;
    initial spare[3] = 3'd3;
    initial spare[4] = 3'd4;
    initial spare[5] = 3'd5;
    initial spare[6] = 3'd6;
    initial spare[7] = 3'd7;

    assign take_valid = (n_free != 4'd0);
    assign take_id = spare[get_ptr];
    assign free_count = n_free;
    wire do_alloc = take_valid && take_ready;
    wire do_rel = give_valid && out_q[give_id];

    always @(posedge clk) begin
        if (rst) begin
            out_q <= 8'd0;
            get_ptr <= 3'd0;
            put_ptr <= 3'd0;
            n_free <= 4'd8;
            spare[0] <= 3'd0;
            spare[1] <= 3'd1;
            spare[2] <= 3'd2;
            spare[3] <= 3'd3;
            spare[4] <= 3'd4;
            spare[5] <= 3'd5;
            spare[6] <= 3'd6;
            spare[7] <= 3'd7;
        end else begin
            if (do_alloc) begin
                out_q[spare[get_ptr]] <= 1'b1;
                get_ptr <= get_ptr + 3'd1;
            end
            if (do_rel) begin
                out_q[give_id] <= 1'b0;
                spare[put_ptr] <= give_id;
                put_ptr <= put_ptr + 3'd1;
            end
            if (do_alloc && !do_rel)
                n_free <= n_free - 4'd1;
            else if (do_rel && !do_alloc)
                n_free <= n_free + 4'd1;
        end
    end

    // free IDs and IDs in use always add up to all of them
    always @(posedge clk) assert (n_free + out_q[0] + out_q[1] + out_q[2] + out_q[3] + out_q[4] + out_q[5] + out_q[6] + out_q[7] == 4'd8);
endmodule

// A 4-entry lookup table of 12-bit keys and 8-bit values; an insert updates the entry that holds its key or takes a free one, so a key is stored at most once. When no entry is free, entries are replaced in turn.
module tlb_cam #(
    parameter KEY_W = 12,
    parameter VAL_W = 8
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             fill_valid,
    output wire             fill_ready,
    input  wire [KEY_W-1:0] fill_key,
    input  wire [VAL_W-1:0] fill_val,
    input  wire             drop_valid,
    input  wire [KEY_W-1:0] drop_key,
    input  wire [KEY_W-1:0] lookup_key,
    output wire             lookup_hit,
    output wire [VAL_W-1:0] lookup_val
);
    localparam N = 4;

    reg [N-1:0] in_use;
    reg [KEY_W-1:0] addr_tag [0:N-1];
    reg [VAL_W-1:0] payload [0:N-1];
    reg [1:0] victim;

    initial in_use = 4'd0;
    initial victim = 2'd0;

    // lookup: every entry compared at once
    reg [N-1:0] entry_hit;
    reg [VAL_W-1:0] lk_val_r;
    integer i0;
    always @(*) begin
        lk_val_r = {VAL_W{1'b0}};
        for (i0 = 0; i0 < N; i0 = i0 + 1) begin
            entry_hit[i0] = in_use[i0] && (addr_tag[i0] == lookup_key);
            if (entry_hit[i0]) lk_val_r = payload[i0];
        end
    end
    assign lookup_hit = |entry_hit;
    assign lookup_val = lk_val_r;

    // insert: the entry holding the key, else the lowest free one
    reg fill_hit, any_free;
    reg [1:0] fill_slot, free_slot;
    integer i1;
    always @(*) begin
        fill_hit = 1'b0;
        fill_slot = 2'd0;
        any_free = 1'b0;
        free_slot = 2'd0;
        for (i1 = N - 1; i1 >= 0; i1 = i1 - 1) begin
            if (in_use[i1] && (addr_tag[i1] == fill_key)) begin
                fill_hit = 1'b1;
                fill_slot = i1;
            end
            if (!in_use[i1]) begin
                any_free = 1'b1;
                free_slot = i1;
            end
        end
    end

    // remove: the entry holding the key, if any
    reg drop_hit;
    reg [1:0] drop_slot;
    integer i2;
    always @(*) begin
        drop_hit = 1'b0;
        drop_slot = 2'd0;
        for (i2 = 0; i2 < N; i2 = i2 + 1)
            if (in_use[i2] && (addr_tag[i2] == drop_key)) begin
                drop_hit = 1'b1;
                drop_slot = i2;
            end
    end

    assign fill_ready = !drop_valid;
    wire [1:0] target = fill_hit ? fill_slot : (any_free ? free_slot : victim);
    wire do_ins = fill_valid && fill_ready;
    wire do_inv = drop_valid && drop_hit;

    always @(posedge clk) begin
        if (rst) begin
            in_use <= 4'd0;
            victim <= 2'd0;
        end else if (do_inv) begin
            in_use[drop_slot] <= 1'b0;
        end else if (do_ins) begin
            in_use[target] <= 1'b1;
            addr_tag[target] <= fill_key;
            payload[target] <= fill_val;
            if (!fill_hit && !any_free) victim <= victim + 2'd1;
        end
    end

    // a lookup matches at most one entry
    always @(posedge clk) assert (entry_hit[0] + entry_hit[1] + entry_hit[2] + entry_hit[3] <= 3'd1);
endmodule

